import type { MeaningPack } from '../../types';

export const taSundaraVerses2: MeaningPack = {
  lang: 'ta',
  texts: {
    'sundarakanda-12': {
      verses: {
        '0.0': 'அந்த மாளிகையின் நடுவில் நின்ற ஹனுமான் சீதையைக் காணும் ஆவலுடன் கொடிவீடுகள், சித்திரசாலைகள், இரவு மாளிகைகள் எங்கும் சென்றான்; ஆனால் அந்த அழகியைக் காணவில்லை.',
        '0.1': 'ராமனின் அன்புக்குரியவளைக் காணாத அந்த மாபெரும் வானரன் எண்ணினான்: “எவ்வளவு தேடியும் மைதிலி கண்ணில் படவில்லை; சீதை உயிருடன் இல்லை என்பது உறுதி.”',
        '0.2': '“தன் கற்பைக் காப்பதிலேயே உறுதியுடன், உயர்ந்தோர் நெறியில் நின்ற அந்தச் சாத்வி ஜானகியைத் தீச்செயலனான இந்த அரக்கர் தலைவன் கொன்றிருக்க வேண்டும்.”',
        '0.3': '“அல்லது அரக்கர் அரசனின் கோர உருவமும், ஒளியிழந்த முகமும், பெரிய வாயும் கொண்ட அந்தப் பெண்களைக் கண்டு ஜனகன் மகள் அச்சத்தாலேயே உயிர் நீத்திருப்பாள்.”',
        '0.4': '“சீதையைக் காணாமலும், எந்த வீரச்செயலும் புரியாமலும், வானரர்களுடன் நீண்ட காலம் கழித்த எனக்குச் சுக்ரீவனிடம் திரும்பிச் செல்ல வழியே இல்லை; அந்த வானரன் வலியவன், கடுமையாகத் தண்டிப்பவன்.”',
        '0.5': '“அந்தப்புரம் முழுவதும் பார்த்தேன், ராவணனின் மனைவியரையும் பார்த்தேன்; ஆனால் கற்புடைய சீதை தென்படவில்லை. என் உழைப்பு வீணாயிற்று.”',
        '0.6': '“நான் திரும்பியதும் ஒன்றுகூடிய வானரர் யாவரும் ‘வீரனே, அங்கே சென்று நீ என்ன செய்தாய், சொல்’ என்று கேட்பார்களே!”',
        '0.7': '“ஜனகன் மகளைக் காணாமல் நான் அவர்களிடம் என்ன சொல்வேன்? கெடு கடந்துவிட்டதால் உண்ணா நோன்பிருந்து உயிர் விடவேண்டியதுதான்.”',
        '0.8': '“கடலின் அக்கரைக்குச் சென்று வந்த என்னிடம் முதியவரான ஜாம்பவானும் அங்கதனும் கூடியிருக்கும் வானரரும் என்ன சொல்வார்கள்?”',
        '0.9': '“மனம் தளராமையே செல்வத்தின் வேர்; மனம் தளராமையே மேலான இன்பம். இதுவரை தேடாத இடங்களில் மீண்டும் தேடுவேன்.”',
        '0.10': '“சோர்வில்லா ஊக்கமே எல்லாச் செயல்களிலும் எப்போதும் ஈடுபடுத்துகிறது; ஒருவன் செய்யும் செயலை அதுவே பயனுள்ளதாக்குகிறது.”',
        '0.11': '“ஆகவே ஊக்கத்துடன் மேலான முயற்சி செய்து, ராவணன் காக்கும், நான் இன்னும் காணாத இடங்களைத் தேடுவேன்.”',
        '0.12': '“மதுக்கூடங்கள், மலர்வீடுகள், சித்திரசாலைகள், விளையாட்டு மாளிகைகள் எல்லாவற்றையும் மீண்டும் மீண்டும் தேடிவிட்டேன்.”',
        '0.13': '“தோட்டங்களுக்கு இடையிலான பாதைகளையும் எல்லா விமானங்களையும் பார்த்துவிட்டேன்” என்று எண்ணி அவன் மீண்டும் தேடத் தொடங்கினான்.',
        '0.14': 'நிலவறைகள், கோயில் மண்டபங்கள், வீடுகளுக்கு அப்பாலுள்ள வீடுகள் எல்லாவற்றையும் மேலே தாவியும் கீழே இறங்கியும், ஆங்காங்கே நின்றும் நடந்தும் தேடினான்.',
        '0.15': 'கதவுகளைத் திறந்தும், கதவுப் பலகைகளைத் தள்ளியும், உள்ளே புகுந்தும் வெளியே வந்தும் அவன் ஒருமுறை கீழே குதிப்பவன் போலவும் ஒருமுறை மேலே தாவுபவன் போலவும் தோன்றினான்.',
        '0.16': 'அந்த மாபெரும் வானரன் எல்லா இடங்களிலும் சுற்றினான்; ராவணனின் அந்தப்புரத்தில் அவன் செல்லாத நான்கு விரல் அளவு இடம் கூட இல்லை.',
        '0.17': 'மதில்களுக்கு இடையிலான தெருக்கள், மேடைகள், கோயில்கள், குழிகள், தாமரைக் குளங்கள் — அனைத்தையும் அவன் பார்த்தான்.',
        '0.18': 'அங்கே ஹனுமான் பலவித வடிவங்களும் கோரத் தோற்றமும் கொண்ட அரக்கியரைக் கண்டான்; ஆனால் ஜனகன் மகளைக் காணவில்லை.',
        '0.19': 'உலகில் இணையற்ற அழகுடைய வித்யாதரப் பெண்களைக் கண்டான்; ஆனால் ராகவனுக்கு இன்பமளிப்பவளைக் காணவில்லை.',
        '0.20': 'அழகிய இடையும் முழுநிலவு போன்ற முகமும் கொண்ட நாகக் கன்னியரைக் கண்டான்; ஆனால் ஜனகன் மகளைக் காணவில்லை.',
        '0.21': 'அரக்கர் வேந்தன் வென்று வலிந்து கவர்ந்து வந்த நாகக் கன்னியரைக் கண்டான்; ஆனால் ஜனகன் மகளைக் காணவில்லை.',
        '0.22': 'வேறு சிறந்த பெண்களைக் கண்டும் அவளைக் காணாததால் நீண்ட கைகளுடைய வாயுமைந்தன் ஹனுமான் மனம் வருந்தினான்.',
        '0.23': 'வானரத் தலைவர்களின் முயற்சியும் தன் கடல் தாண்டலும் வீணானதைக் கண்டு வாயுமைந்தன் மீண்டும் கவலையில் ஆழ்ந்தான்.',
        '0.24': 'விமானத்திலிருந்து இறங்கிய வாயுமைந்தன் ஹனுமான் துயரால் மனம் கலங்கிச் சிந்தனையில் ஆழ்ந்தான்.',
        '0.25': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் பன்னிரண்டாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-13': {
      verses: {
        '0.0': 'விமானத்திலிருந்து மதிலின் மேல் தாவிய வானரப் படைத்தலைவன் ஹனுமான் வேகத்தால் மேகங்களுக்கிடையே மின்னல் போலத் திகழ்ந்தான்.',
        '0.1': 'ராவணனின் மாளிகைகள் அனைத்தையும் சுற்றி வந்தும் ஜானகியைக் காணாத வானரன் ஹனுமான் தனக்குள் இவ்வாறு சொன்னான்:',
        '0.2': '“ராமனுக்கு இனியதைச் செய்ய இலங்கையை முழுவதும் அலசிவிட்டேன்; ஆயினும் அங்கமெல்லாம் அழகுடைய வைதேகி சீதையைக் காணவில்லை.”',
        '0.3': '“சிறு குட்டைகள், ஏரிகள், தடாகங்கள், ஓடைகள், ஆறுகள், சதுப்புக் காடுகள், அரண்கள், மலைகள் —”',
        '0.4': '“— இந்த நிலம் முழுவதும் தேடியும் ஜானகி தென்படவில்லை. கழுகரசன் ஸம்பாதி சீதை இங்கே ராவணன் மாளிகையில் இருப்பதாகச் சொன்னானே; ஏன் காணப்படவில்லை?”',
        '0.5': '“ராவணன் வலிந்து கவர்ந்த வைதேகி, மைதிலி, ஜனகன் மகளான சீதை வேறு வழியின்றி அவனுக்கு அடங்கியிருப்பாளோ?”',
        '0.6': '“ராமனின் அம்புகளுக்கு அஞ்சிச் சீதையைத் தூக்கிக்கொண்டு விரைந்து பறந்த அரக்கனிடமிருந்து அவள் வழியிடையே நழுவி விழுந்திருப்பாள் என்று எண்ணுகிறேன்.”',
        '0.7': '“அல்லது சித்தர்கள் செல்லும் வான்வழியில் கொண்டுசெல்லப்படும்போது கடலைக் கண்டு அந்த உத்தமியின் இதயம் நின்றுபோயிருக்கலாம்.”',
        '0.8': '“அல்லது ராவணனின் பெருவேகத்தாலும் அவன் கைகளின் பிடியாலும் நசுங்கி அந்தப் பெருங்கண்ணாள் உயிர் துறந்திருக்கலாம்.”',
        '0.9': '“அல்லது அவன் கடலுக்கு மேல் உயரத்தில் செல்லும்போது திமிறிய ஜனகன் மகள் கடலில் விழுந்திருப்பாள்.”',
        '0.10': '“ஐயோ, அல்லது உறவினர் இல்லாது தன் கற்பைக் காத்துவந்த பாவம் சீதையை இந்த இழிந்த ராவணன் தின்றுவிட்டிருப்பான்.”',
        '0.11': '“அல்லது குற்றமற்ற அந்தக் கருவிழியாளை அரக்கர் வேந்தனின் தீய எண்ணமுடைய மனைவியர் தின்றிருப்பார்கள்.”',
        '0.12': '“முழுநிலவு போன்றதும் தாமரை இதழ்க் கண்களுடையதுமான ராமனின் முகத்தையே தியானித்தபடி அந்தப் பரிதாபத்துக்குரியவள் மாண்டிருப்பாள்.”',
        '0.13': '“‘ஹா ராமா! ஹா லக்ஷ்மணா! ஹா அயோத்தியே!’ என்று மிகவும் புலம்பி வைதேகி உடலை விட்டிருப்பாள்.”',
        '0.14': '“அல்லது ராவணன் மாளிகையில் எங்கோ மறைத்து வைக்கப்பட்டு, கூண்டிலுள்ள நாகணவாய்ப்புள் போல அந்த இளம்பெண் கதறிக்கொண்டிருக்கலாம்.”',
        '0.15': '“ஜனகன் குலத்தில் பிறந்தவள், ராமனின் மனைவி, மெல்லிடையாள், தாமரைக் கண்ணாள் — அவள் எப்படி ராவணனுக்கு வசப்படுவாள்?”',
        '0.16': '“ஜனகன் மகள் அழிந்தாளோ, மறைந்தாளோ, இறந்தாளோ — மனைவியை மிகவும் நேசிக்கும் ராமனிடம் இதைச் சொல்வது தகாது.”',
        '0.17': '“சொன்னாலும் குற்றம், சொல்லாவிட்டாலும் குற்றம்; இப்போது என்ன செய்வது? இது எனக்குக் கடினமான இக்கட்டாகத் தோன்றுகிறது.”',
        '0.18': '“இந்நிலையில் காலத்துக்கேற்றதும் தகுந்ததும் எது?” என்று ஹனுமான் மீண்டும் மீண்டும் சிந்தித்தான்.',
        '0.19': '“சீதையைக் காணாமல் இங்கிருந்து வானர அரசனின் நகருக்குச் சென்றால் என் ஆண்மைக்கு என்ன மதிப்பு?”',
        '0.20': '“என் கடல் தாண்டலும், இலங்கையில் நுழைந்ததும், அரக்கர்களைக் கண்டதும் எல்லாம் வீணாகும்.”',
        '0.21': '“நான் கிஷ்கிந்தையை அடைந்ததும் சுக்ரீவனும் கூடியுள்ள வானரரும் தசரதனின் அந்த இரு மைந்தரும் என்ன சொல்வார்கள்?”',
        '0.22': '“சென்று காகுத்ஸ்தனிடம் ‘நான் சீதையைக் காணவில்லை’ என்ற கடுஞ்சொல்லைச் சொன்னால் அவன் உயிர் துறப்பான்.”',
        '0.23': '“சீதையைப் பற்றிய கடுமையான, கொடிய, கூர்மையான, புலன்களைச் சுடும் தீய செய்தியைக் கேட்டு அவன் உயிர் வாழமாட்டான்.”',
        '0.24': '“துயரில் ஆழ்ந்து சாவை நாடும் அவனைக் கண்டு, அவனிடம் பேரன்பு கொண்ட அறிவாளி லக்ஷ்மணனும் உயிர் வாழமாட்டான்.”',
        '0.25': '“இரு சகோதரர்களும் அழிந்ததைக் கேட்டுப் பரதனும் இறப்பான்; பரதன் இறந்ததைக் கண்டு சத்ருக்னனும் உயிர் வாழமாட்டான்.”',
        '0.26': '“மைந்தர்கள் இறந்ததைக் கண்டு அன்னையர் கௌசல்யை, சுமித்திரை, கைகேயி ஆகியோரும் உயிர் வாழமாட்டார்கள்; ஐயமில்லை.”',
        '0.27': '“நன்றியுடையவனும் சொல் தவறாதவனுமான வானர அரசன் சுக்ரீவன் ராமனின் அந்நிலையைக் கண்டு உயிர் துறப்பான்.”',
        '0.28': '“மனமுடைந்து, வேதனையுற்று, ஏங்கி, மகிழ்ச்சியிழந்து, கணவன் துயரால் வாடும் பாவம் ருமையும் உயிர் துறப்பாள்.”',
        '0.29': '“வாலியின் மறைவுத் துயரால் ஏற்கெனவே வாடி மெலிந்த அரசி தாரையும் உயிர் விடுவாள்.”',
        '0.30': '“தாய் தந்தையர் அழிவாலும் சுக்ரீவனின் துன்பத்தாலும் இளவரசன் அங்கதனும் உயிர் துறப்பான்.”',
        '0.31': '“தலைவனின் துயரால் மூழ்கிய காட்டு வானரர் உள்ளங்கைகளாலும் முஷ்டிகளாலும் தலையில் அடித்துக்கொள்வார்கள்.”',
        '0.32': '“இன்சொல், கொடை, மதிப்பு ஆகியவற்றால் புகழ்பெற்ற வானர அரசன் போற்றி வளர்த்த வானரர் உயிர் துறப்பார்கள்.”',
        '0.33': '“இனி அந்தச் சிறந்த வானரர் காடுகளிலோ மலைகளிலோ தனிமையான இடங்களிலோ கூடி விளையாடமாட்டார்கள்.”',
        '0.34': '“தலைவனின் துன்பத்தால் வருந்திய அவர்கள் மக்கள், மனைவியர், அமைச்சர்களுடன் மலை முகடுகளிலிருந்து சமதளத்திலும் கரடுமுரடான நிலத்திலும் குதிப்பார்கள்.”',
        '0.35': '“வானரர் நஞ்சு, தூக்கு, தீப்புகுதல், உண்ணாநோன்பு அல்லது ஆயுதம் ஆகியவற்றை நாடுவார்கள்.”',
        '0.36': '“நான் திரும்பினால் பயங்கரமான கதறல் எழும்; இக்ஷ்வாகு குலமும் காட்டு வானரரும் அழிவார்கள்.”',
        '0.37': '“ஆகவே நான் இங்கிருந்து கிஷ்கிந்தை நகருக்குப் போகமாட்டேன்; மைதிலி இல்லாமல் சுக்ரீவனைக் காண என்னால் இயலாது.”',
        '0.38': '“நான் போகாமல் இங்கேயே இருந்தால் அறவழி நிற்கும் அந்த இரு மாவீரர்களும் விரைவுடைய வானரரும் நம்பிக்கையுடன் உயிர் வாழ்வார்கள்.”',
        '0.39': '“ஜனகன் மகளைக் காணாமல், கைக்கோ வாய்க்கோ தானே வருவதை உண்டு, கட்டுப்பாட்டுடன் மரத்தடியில் வாழும் வானப்ரஸ்தனாவேன்.”',
        '0.40': '“கிழங்கு, கனி, நீர் நிறைந்த கடற்கரைப் பகுதியில் சிதை அமைத்து அரணிக் கட்டையில் பிறந்த எரியும் தீயில் புகுவேன்.”',
        '0.41': '“அல்லது முறைப்படி உண்ணாநோன்பிருந்து அமர்ந்திருக்கும் என் உடலைக் காகங்களும் கொடிய விலங்குகளும் தின்னும்.”',
        '0.42': '“இதுவும் முனிவர்கள் ஏற்ற உயிர்விடும் வழியே என்பது என் கருத்து: ஜானகியைக் காணாவிட்டால் முறைப்படி நீரில் புகுவேன்.”',
        '0.43': '“சீதையைக் காணாததால் நன்கு வேரூன்றிய, அழகிய, புகழ்மிக்க என் கீர்த்தி மாலை என்றென்றைக்குமாக அறுந்துவிட்டது.”',
        '0.44': '“அல்லது கட்டுப்பாட்டுடன் மரத்தடியில் வாழும் தவசியாவேன்; அந்தக் கருவிழியாளைக் காணாமல் இங்கிருந்து திரும்பமாட்டேன்.”',
        '0.45': '“சீதையைக் காணாமல் நான் திரும்பினால் அங்கதனும் அவனுடன் உள்ள வானரர் அனைவரும் உயிர் வாழமாட்டார்கள்.”',
        '0.46': '“ஆனால் இறப்பில் பல தீமைகள் உண்டு; உயிரோடிருப்பவன் நலம் பெறுவான். ஆகவே உயிரைக் காத்துக்கொள்வேன்; உயிரோடிருந்தால் மீண்டும் சேர்வது உறுதி.”',
        '0.47': 'இவ்வாறு பலவகைத் துயரத்தை மனத்தில் சுமந்த அந்த வானர வேழம் அப்போது துயரத்தின் கரையை அடைய முடியவில்லை.',
        '0.48': 'அப்போது துணிவுடைய அந்த வானர வேழம் வீரத்தைக் கைக்கொண்டு எண்ணினான்: “அல்லது பெருவலிமையுள்ள பத்துத்தலை ராவணனையே கொல்வேன்; சீதை கவரப்பட்டிருந்தாலும் பழி தீர்க்கப்படும்.”',
        '0.49': '“அல்லது அவனைத் தூக்கிக்கொண்டு கடலுக்கு மேலாகக் கொண்டுசென்று, பசுபதிக்குப் பலிப்பொருளைப் படைப்பது போல ராமனிடம் ஒப்படைப்பேன்.”',
        '0.50': 'சீதையைக் காணாது இவ்வாறு கவலையில் ஆழ்ந்து, சிந்தனையும் துயரும் சூழ்ந்த மனத்துடன் அந்த வானரன் எண்ணினான்:',
        '0.51': '“ராமனின் புகழ்மிக்க மனைவி சீதையைக் காணும் வரை இந்த இலங்கை நகரை மீண்டும் மீண்டும் தேடுவேன்.”',
        '0.52': '“ஸம்பாதியின் சொல்லை நம்பி நான் ராமனை இங்கே அழைத்து வந்தாலும், மனைவியைக் காணாத ராகவன் எல்லா வானரரையும் எரித்துவிடுவான்.”',
        '0.53': '“உணவையும் புலன்களையும் கட்டுப்படுத்தி இங்கேயே இருப்பேன்; என்னால் அந்த மனிதரும் வானரரும் அழியக்கூடாது.”',
        '0.54': '“இதோ பெருமரங்கள் நிறைந்த பரந்த அசோகவனம் இருக்கிறது; இதை நான் இன்னும் தேடவில்லை, இதனுள் செல்வேன்.”',
        '0.55': '“வசுக்கள், ருத்திரர், ஆதித்யர், அஸ்வினி தேவர், மருத்துக்கள் ஆகியோரை வணங்கி, அரக்கர்களின் துயரைப் பெருக்குபவனாகச் செல்வேன்.”',
        '0.56': '“அரக்கர்களை வென்று, தவசிக்குச் சித்தி கிடைப்பது போல இக்ஷ்வாகு குலத்தை மகிழ்விக்கும் தேவியை ராமனிடம் ஒப்படைப்பேன்.”',
        '0.57': 'சற்று நேரம் சிந்தித்து, கவலையால் புலன்கள் கலங்கிய நீண்ட கைகளுடைய வாயுமைந்தன் ஹனுமான் எழுந்தான்.',
        '0.58': '“லக்ஷ்மணனுடன் கூடிய ராமனுக்கு வணக்கம்; ஜனகன் மகளான அந்தத் தேவிக்கு வணக்கம். ருத்திரன், இந்திரன், யமன், வாயு ஆகியோருக்கு வணக்கம்; சந்திரன், அக்னி, மருத் கணங்களுக்கு வணக்கம்.”',
        '0.59': 'அவர்கள் அனைவரையும் சுக்ரீவனையும் வணங்கி, எல்லாத் திசைகளையும் நோக்கி, மாருதி அசோகவனத்தை நோக்கிச் சென்றான்.',
        '0.60': 'முதலில் மனத்தாலேயே அழகிய அசோகவனத்தை அடைந்து, வாயுமைந்தனான அந்த வானரன் அடுத்து நடக்கவேண்டியதைச் சிந்தித்தான்.',
        '0.61': '“மரங்கள் அடர்ந்ததும் எல்லா வகையிலும் பேணப்பட்டதுமான அந்தப் புனித அசோகவனம் நிச்சயமாக அரக்கர்களால் நிறைந்திருக்கும்.”',
        '0.62': '“அங்கே நியமிக்கப்பட்ட காவலர்கள் மரங்களைக் காத்துக்கொண்டிருப்பார்கள்; உலகின் உயிரான பகவான் வாயுவும் அங்கே மிகுந்த வேகத்துடன் வீசுவதில்லை.”',
        '0.63': '“ராமனின் காரியத்துக்காகவும் ராவணன் கண்ணில் படாமலிருக்கவும் என் உடலைச் சிறியதாக்கியுள்ளேன்; முனிவர் கணங்களுடன் தேவர் அனைவரும் எனக்கு இங்கே வெற்றியை அருளட்டும்.”',
        '0.64': '“சுயம்பு பகவான் பிரம்மாவும், தேவர்களும், தவசிகளும், அக்னியும், வாயுவும், வஜ்ரம் ஏந்திய இந்திரனும் எனக்கு வெற்றியை அருளட்டும்;”',
        '0.65': '“பாசம் ஏந்திய வருணனும், சந்திர சூரியரும், மகாத்மாக்களான அஸ்வினி தேவரும், மருத்துக்கள் அனைவரும்;”',
        '0.66': '“எல்லா உயிர்களும், உயிர்களின் தலைவனும், வழியில் உலவும் கண்ணுக்குப் புலப்படாத மற்றவர்களும் எனக்கு வெற்றியை அருள்வார்கள்.”',
        '0.67': '“உயர்ந்த நாசி, வெண்மையான பற்கள், களங்கமற்ற, தூய புன்னகை, தாமரை இதழ்க் கண்கள் கொண்ட, தெளிந்த நிலவு போல் ஒளிரும் அந்த உத்தமியின் முகத்தை நான் எப்போது காண்பேன்?”',
        '0.68': '“அந்த இழிந்தவன், கீழோன், கொடிய உருவினன், அச்சமூட்டும் அணிகள் பூண்டவனால் வலிந்து அடக்கப்பட்ட அந்த அபலைத் தவமங்கை இன்று என் கண்ணில் எப்படிப் படுவாள்?”',
        '0.69': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் பதின்மூன்றாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-14': {
      verses: {
        '0.0': 'சற்றுநேரம் சிந்தித்து மனத்தாலேயே அவளை அடைந்த பேரொளியுடைய ஹனுமான் அந்த மாளிகைத் தோட்டத்தின் மதில் மேல் தாவினான்.',
        '0.1': 'உடலெல்லாம் சிலிர்த்து மதில்மேல் நின்ற மாபெரும் வானரன் வசந்தத் தொடக்கம் போல நுனிகளில் பூத்திருந்த பலவகை மரங்களைக் கண்டான்.',
        '0.2': 'சால மரங்கள், அசோகங்கள், அழகிய பவ்யங்கள், நன்கு மலர்ந்த சண்பகங்கள், உத்தாலகங்கள், நாகமரங்கள், மாமரங்கள், கபிமுக மரங்கள் —',
        '0.3': '— மாந்தோப்புகள் நிறைந்து நூற்றுக்கணக்கான கொடிகள் படர்ந்த அந்த மரச்சோலையில், நாணிலிருந்து விடுபட்ட அம்பு போல அவன் பாய்ந்தான்.',
        '0.4': 'பறவைகளின் ஒலியால் எதிரொலித்ததும், சுற்றிலும் வெள்ளி, பொன் மரங்களால் சூழப்பட்டதுமான அந்த அற்புதச் சோலையில் நுழைந்து,',
        '0.5': 'பறவைகளாலும் மான் கூட்டங்களாலும் வண்ணமயமானதும், ஓவியம் போன்ற காடுகளுடையதும், உதிக்கும் சூரியன் போல ஒளிர்ந்ததுமான அதை வலிமைமிக்க ஹனுமான் கண்டான்.',
        '0.6': 'மலர்களும் கனிகளும் நிறைந்த பலவகை மரங்களால் சூழப்பட்ட அது, மதமுற்ற குயில்களும் பிருங்கராஜப் பறவைகளும் எப்போதும் வாழும் இடமாக இருந்தது.',
        '0.7': 'பருவத்தில் மக்களை மகிழ்வித்ததும், மதமுற்ற விலங்கு பறவைகளால் நிறைந்ததும், களிப்புற்ற மயில்களின் அகவலால் ஒலித்ததும், பலவகைப் பறவைக் கூட்டங்கள் நிறைந்ததுமான சோலை அது.',
        '0.8': 'அழகிய உடலுடைய, பழியற்ற அரசகுமாரியைத் தேடியபடி வானரன் நிம்மதியாக உறங்கிய பறவைகளை எழுப்பினான்.',
        '0.9': 'மேலே பறந்த பறவைகளின் சிறகுக் காற்றால் அசைந்த மரங்கள் பல வண்ண மலர் மழையைப் பொழிந்தன.',
        '0.10': 'மலர்களால் மூடப்பட்ட வாயுமைந்தன் ஹனுமான் அசோகவனத்தின் நடுவில் மலர்களாலான மலை போல் விளங்கினான்.',
        '0.11': 'மரத்தொகுதிகளிடையே எல்லாத் திசைகளிலும் ஓடிய வானரனைக் கண்டு உயிர்கள் யாவும் அவனை வசந்தனே என்று எண்ணின.',
        '0.12': 'மரங்களிலிருந்து உதிர்ந்த பலவகை மலர்களால் மூடப்பட்ட அந்த நிலம் அணிபூண்ட இளம்பெண் போலத் திகழ்ந்தது.',
        '0.13': 'விரைவுடைய வானரன் வேகமாக உலுக்கிய அந்த மரங்கள் அப்போது பல வண்ண மலர்களை உதிர்த்தன.',
        '0.14': 'இலைகள் உதிர்ந்த உச்சிகளும் உதிர்ந்த பூ, கனிகளும் கொண்ட அம்மரங்கள், தோற்று ஆடை அணிகலன்களைக் கழற்றிப்போட்ட சூதாடிகள் போலத் தோன்றின.',
        '0.15': 'விரைவுடைய ஹனுமான் உலுக்கிய கனிகள் நிறைந்த அந்தச் சிறந்த மரங்கள் விரைவில் மலர், இலை, கனிகளை உதிர்த்தன.',
        '0.16': 'வாயுமைந்தன் உலுக்கிய அம்மரங்கள் எல்லாம் பறவைக் கூட்டங்கள் இன்றி, அடிமரம் மட்டுமே எஞ்சி வெறுமையாயின.',
        '0.17': 'கூந்தல் கலைந்து, பூச்சு அழிந்து, இதழ்ச்சுவை பருகப்பட்டு, நகங்களாலும் பற்களாலும் குறியிடப்பட்ட இளம்பெண் போல —',
        '0.18': '— அவ்வாறே அவனது வால், கைகள், கால்களால் மிதிபட்டு, சிறந்த மரங்கள் முறிந்த அசோகவனமும் காட்சியளித்தது.',
        '0.19': 'மழைக்காலத்தில் காற்று மேகக் கூட்டங்களை வேகமாகச் சிதறடிப்பது போல, வானரன் பெருங்கொடிகளின் தோரணங்களை வேகமாக அறுத்தெறிந்தான்.',
        '0.20': 'அங்கே சுற்றிய வானரன் மணிகளாலும் வெள்ளியாலும் பொன்னாலும் பதிக்கப்பட்ட மனங்கவரும் தரைகளைக் கண்டான்.',
        '0.21': 'சிறந்த நீர் நிறைந்து, ஆங்காங்கே விலையுயர்ந்த மணிப்படிகள் அமைந்த பலவடிவக் கிணறுகளையும் கண்டான்;',
        '0.22': 'முத்து, பவள மணலும் பளிங்குத் தரையும் கொண்டு, கரைகளில் வளர்ந்த அற்புதப் பொன் மரங்களால் அவை அழகுபெற்றிருந்தன;',
        '0.23': 'அவற்றில் மலர்ந்த தாமரை, குவளைக் காடுகளும், சக்ரவாகப் பறவைகளின் அழகும், நீர்க்கோழிகளின் கூவலும், அன்னம், நாரைகளின் ஒலியும் இருந்தன;',
        '0.24': 'சுற்றிலும் மரங்கள் சூழ்ந்த, அமுதம் போன்ற நீருடைய, மங்கலமான நீண்ட ஓடைகளால் அவை அழகுபடுத்தப்பட்டிருந்தன;',
        '0.25': 'நூற்றுக்கணக்கான கொடிகள் படர்ந்து, சந்தானக மலர்களால் மூடப்பட்டு, பல புதர்கள் நிறைந்து, இடையிடையே அலரிச் செடிகள் கொண்ட இடங்கள் அவை.',
        '0.26': 'பின்னர் வானரப் புலி மழைமேகம் போன்றதும், உயர்ந்த சிகரங்களும் அற்புத முகடுகளும் கொண்டதும், சுற்றிலும் சிறு முகடுகளால் சூழப்பட்டதுமான மலையைக் கண்டான்;',
        '0.27': 'கல் வீடுகள் நிறைந்து, பலவகை மரங்களால் மூடப்பட்ட, உலகிலேயே எழில்மிக்க மலை அது.',
        '0.28': 'காதலனின் மடியிலிருந்து துள்ளி விழுந்த காதலி போல, அந்த மலையிலிருந்து விழும் ஆற்றை வானரன் கண்டான்.',
        '0.29': 'நீரில் தாழ்ந்த நுனிகளுடைய மரங்களால் அழகுபெற்ற அது, அன்புறவினர் தடுத்து நிறுத்தும் சினமுற்ற இளம்பெண் போலத் தோன்றியது.',
        '0.30': 'நீர் மீண்டும் திரும்பிய இடத்தில், சமாதானமடைந்து மறுபடி காதலனிடம் வந்த காதலி போல அதை மாபெரும் வானரன் கண்டான்.',
        '0.31': 'அதன் அருகிலேயே வானரப் புலி வாயுமைந்தன் ஹனுமான் பலவகைப் பறவைகள் நிறைந்த தாமரைக் குளங்களைக் கண்டான்;',
        '0.32': 'குளிர்ந்த நீர் நிறைந்து, சிறந்த மணிப்படிகளுடன், முத்து மணலால் ஒளிர்ந்த செயற்கை ஏரியையும் கண்டான்;',
        '0.33': 'பலவகை மான் கூட்டங்களால் வண்ணமயமாகி, ஓவியம் போன்ற காடுகளும் விஸ்வகர்மா கட்டிய பெரும் மாளிகைகளும் கொண்டது அது;',
        '0.34': 'சுற்றிலும் செயற்கைக் காடுகளால் அணிசெய்யப்பட்டிருந்தது; அங்குள்ள மரங்கள் யாவும் பூவும் கனியும் நிறைந்திருந்தன,',
        '0.35': 'எல்லாவற்றுக்கும் குடைகளும் திண்ணைகளும் பொன் மேடைகளும் இருந்தன; பல கொடிப் படர்ச்சிகளாலும் அடர்ந்த இலைகளாலும் அது மூடப்பட்டிருந்தது.',
        '0.36': 'சுற்றிலும் பொன் மேடைகளால் சூழப்பட்ட, பொன்போல் ஒளிரும் ஒரு சிம்சுபா மரத்தை மாபெரும் வானரன் கண்டான்.',
        '0.37': 'அவன் நிலப்பகுதிகளையும் மலையூற்றுகளையும் தீப்போல் ஒளிரும் பிற பொன் மரங்களையும் கண்டான்.',
        '0.38': 'மேரு மலையின் ஒளி போன்ற அம்மரங்களின் பிரகாசத்தில், வீரனான அந்த வானரன் தானே முழுவதும் பொன்னாகிவிட்டதாக உணர்ந்தான்.',
        '0.39': 'காற்றில் அசைந்து நூற்றுக்கணக்கான சிறுமணிகளின் ஒலியை எழுப்பிய அந்தப் பொன் மரக் கூட்டங்களைக் கண்டு அவன் வியப்படைந்தான்.',
        '0.40': '— நுனிகளில் பூத்து, இளந்தளிர்கள் கொண்ட அழகிய மரங்கள் அவை. பெருவேகமுடைய வானரன் இலைகள் அடர்ந்த அந்தச் சிம்சுபா மரத்தில் ஏறி எண்ணினான்:',
        '0.41': '“ராமனைக் காண ஏங்கி, துயரால் வாடி, இங்குமங்கும் திரியும் வைதேகியை இங்கிருந்தே காண்பேன்.”',
        '0.42': '“அந்தத் தீயவனின் இந்த அசோகவனம் உண்மையில் இனிமையானது; சந்தனம், சண்பகம், மகிழ மரங்களால் அழகுபெற்றது.”',
        '0.43': '“பறவைக் கூட்டங்கள் நாடும் இந்த அழகிய தாமரைக் குளத்துக்கு அரசி ஜானகி நிச்சயம் வருவாள்.”',
        '0.44': '“காட்டில் உலவுவதில் தேர்ந்தவளும், ராகவனின் அன்புக்குரிய கற்புடையவளும், அழகியுமான அரசி ஜானகி நிச்சயம் இங்கே வருவாள்.”',
        '0.45': '“அல்லது இந்தச் சோலையை நன்கறிந்த, ராமனை எண்ணி மெலிந்த அந்த மான்விழியாள் இன்று இங்கே வருவாள்.”',
        '0.46': '“ராமனின் பிரிவுத் துயரால் வெந்து, காட்டு வாழ்க்கையை விரும்பி, எப்போதும் வனத்தில் உலவும் அந்த அழகிய கண்ணுடைய தேவி இங்கே வருவாள்.”',
        '0.47': '“ராமனின் அன்புக்குரிய உத்தமியும் கற்புடையவளுமான ஜனகன் மகள் முன்பு எப்போதும் காட்டு உயிர்களை நேசித்தவள்.”',
        '0.48': '“சந்தியா வழிபாட்டில் மனம் கொண்ட அழகிய நிறமுடைய இளம் ஜானகி, சந்தியாவந்தனத்துக்காக இந்தத் தூய நீருடைய ஆற்றுக்கு நிச்சயம் வருவாள்.”',
        '0.49': '“மங்கலமானவளும் மன்னர் மன்னனான ராமனின் மதிப்புக்குரிய மனைவியுமான அவளுக்கு இந்த அழகிய அசோகவனம் ஏற்றதே.”',
        '0.50': '“நிலவு முகமுடைய அந்தத் தேவி உயிரோடிருந்தால் குளிர்ந்த நீருடைய இந்த ஆற்றுக்குக் கட்டாயம் வருவாள்.”',
        '0.51': 'இவ்வாறு எண்ணிய மகாத்மா ஹனுமான் மன்னர் தலைவனின் மனைவிக்காகக் காத்திருந்து, பூத்த அடர்ந்த இலைகளுடைய மரத்தில் மறைந்து எல்லாவற்றையும் கவனித்தான்.',
        '0.52': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் பதினான்காம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-15': {
      verses: {
        '0.0': 'அங்கேயே இருந்து மைதிலியைத் தேடியபடி, நிலம் முழுவதையும் நோக்கி, அவன் அச்சோலையைச் சுற்றிலும் பார்த்தான் —',
        '0.1': 'சந்தானகக் கொடிகளாலும் மரங்களாலும் அழகுபெற்று, தெய்வீக மணமும் சுவையும் நிறைந்து, எங்கும் அணிசெய்யப்பட்ட;',
        '0.2': 'நந்தனவனம் போன்று, விலங்கு பறவைகள் நிறைந்து, மாடங்களும் மாளிகைகளும் நெருங்கி, குயில்களின் கூவலால் ஒலிக்கும்;',
        '0.3': 'பொற்குவளை, தாமரைக் குளங்களால் அழகுபெற்று, பல இருக்கைகளும் கம்பளங்களும் நிலவறைகளும் கொண்ட;',
        '0.4': 'எல்லாப் பருவங்களின் அழகிய மலர்களும் கனிதரும் மரங்களும் மலர்ந்த அசோகங்களின் எழிலும் கொண்டு கதிர் உதயம் போல ஒளிரும் —',
        '0.5': 'அங்கிருந்த மாருதி அதை எரிவது போலக் கண்டான்; பறவைகள் மீண்டும் மீண்டும் அதன் கிளைகளை இலையற்றவையாக்குவது போலிருந்தது,',
        '0.6': 'நூற்றுக்கணக்கான வண்ணப் பூங்கொத்துகள் உதிர்ந்தன; துயர் போக்கும் அசோகங்கள் அடிவரை மலர்களால் நிறைந்திருந்தன;',
        '0.7': 'மலர்ப் பாரத்தால் நிலத்தைத் தொடுவது போன்ற மலர்ந்த கர்ணிகாரங்களும் நன்கு பூத்த பலாச மரங்களும் இருந்தன.',
        '0.8': 'அவற்றின் ஒளியால் அவ்விடம் எங்கும் எரிவது போலத் தோன்றியது; புன்னை, ஏழிலைப்பாலை, சண்பகம், உத்தாலகம் —',
        '0.9': 'ஆழ வேரூன்றி நன்கு மலர்ந்த பல மரங்கள் அங்கே திகழ்ந்தன; சில பொன்போலவும், சில தீக்கொழுந்து போலவும் ஒளிர்ந்தன,',
        '0.10': 'சில கருமையான மை போல — அங்கே ஆயிரக்கணக்கான அசோகங்கள் இருந்தன. அது தேவர்களின் நந்தவனம் போலவும் அற்புதமான சைத்ரரதம் போலவும் இருந்தது;',
        '0.11': 'அவற்றையும் மிஞ்சுவது போல, எண்ணற்கரிய, தெய்வீகமான, எழில் நிறைந்த, மலர்களாகிய விண்மீன்கள் நிறைந்த இரண்டாம் வானம் போல இருந்தது,',
        '0.12': 'நூற்றுக்கணக்கான மலர் ரத்தினங்களால் ஐந்தாம் கடல் போல வண்ணமயமாகி, எல்லாப் பருவ மலர்களாலும் தேன்மணம் கமழும் மரங்களாலும் நிறைந்த,',
        '0.13': 'விலங்கு பறவைகளின் பலவித ஒலிகளால் எதிரொலித்து, பல நறுமணங்களைப் பரப்பும், புனித மணமுடைய மனங்கவர் உத்யானம் அது;',
        '0.14': 'மலைகளின் அரசன் போல நறுமணம் நிறைந்த இரண்டாம் கந்தமாதனம் போல இருந்தது. அந்த அசோகவனத்தில் வானரரில் சிறந்தவன் —',
        '0.15': 'அருகிலேயே ஆயிரம் தூண்களின் மேல் நின்ற, கயிலை போல வெண்மையான கம்பீரமான கோயில் மாளிகையைக் கண்டான்;',
        '0.16': 'பவளப் படிகளும் புடமிட்ட பொன் மேடைகளும் கொண்டு, கண்களைக் கவர்வது போல, எழிலால் ஒளிர்ந்த,',
        '0.17': 'களங்கமற்றதும், உயரத்தால் வானைக் கீறுவது போன்றதுமான அதைக் கண்டான். பின்னர் அழுக்கடைந்த ஆடை அணிந்து, அரக்கியரால் சூழப்பட்ட —',
        '0.18': 'உண்ணா நோன்பால் மெலிந்து, துயருற்று, மீண்டும் மீண்டும் பெருமூச்செறியும், வளர்பிறைத் தொடக்கத்தின் தூய பிறைநிலவு போன்ற ஒருத்தியைக் கண்டான் —',
        '0.19': 'புகை வலையால் மூடப்பட்ட தீக்கொழுந்து போல, அவளுடைய அழகிய ஒளி மங்கலாகவே தெரிந்தது;',
        '0.20': 'அழுக்கடைந்த ஒரே சிறந்த மஞ்சள் ஆடையுடன், சேறு படிந்து, அணிகலன்கள் இன்றி, அவள் தாமரையற்ற குளம் போல இருந்தாள்;',
        '0.21': 'துன்புற்று, துயரால் வெந்து, மெலிந்த அந்தத் தவமங்கை செவ்வாய்க் கோளால் வாட்டப்பட்ட ரோகிணி போல இருந்தாள்;',
        '0.22': 'கண்ணீர் நிறைந்த முகத்துடன், துயருற்று, உண்ணாமையால் மெலிந்து, துயரச் சிந்தனையில் ஆழ்ந்து, எப்போதும் துன்பத்திலேயே மூழ்கியவள்;',
        '0.23': 'தன் அன்புக்குரியவனைக் காணாமல் அரக்கியர் கூட்டத்தையே கண்ட அவள், தன் மந்தையிலிருந்து பிரிந்து நாய்க் கூட்டத்தால் சூழப்பட்ட பெண்மான் போல இருந்தாள்;',
        '0.24': 'கருநாகம் போன்ற, இடைவரை தொங்கும் ஒற்றைச் சடையுடன், மழைக்காலம் முடிந்தபோது கருநீலக் காட்டு வரிசை கொண்ட பூமி போல இருந்தாள்;',
        '0.25': 'இன்பத்துக்கே உரியவளும், துயரால் வெந்தவளும், துன்பங்களை அறியாதவளும், மிகவும் அழுக்கடைந்து மெலிந்தவளுமான அந்தப் பெருங்கண்ணாளைக் கண்டு,',
        '0.26': 'தக்க காரணங்களால் இவளே சீதை என்று ஊகித்தான் — விரும்பிய உருவெடுக்கும் அரக்கன் அன்று கவர்ந்து செல்லும்போது காணப்பட்டவள் இவளே.',
        '0.27': '“அப்போது காணப்பட்ட அதே வடிவமே இந்தப் பெண்ணுடையது.” முழுநிலவு முகமும், அழகிய புருவமும், அழகிய உருண்ட மார்பகங்களும் கொண்டவள்,',
        '0.28': 'தன் ஒளியால் எல்லாத் திசைகளின் இருளையும் போக்கும் அந்தத் தேவி, கருநீலக் கழுத்தும், கோவைப்பழ இதழும், மெல்லிடையும், அழகிய உடல்வாகும் கொண்டவள்,',
        '0.29': 'தாமரை இதழ்க் கண்ணுடைய சீதை மன்மதனின் ரதி போல, உலகனைத்துக்கும் இனியவளாக, முழுநிலவின் ஒளி போல இருந்தாள்;',
        '0.30': 'அழகிய உடலுடைய அவள் விரதம் பூண்ட தவமங்கை போலத் தரையில் அமர்ந்திருந்தாள்; அஞ்சியவளாய், நாகராஜனின் மனைவி போலப் பெருமூச்செறிந்தாள்;',
        '0.31': 'பரவிய பெரும் துயர வலையால், புகை வலையில் ஒட்டிய தீக்கொழுந்து போல அவள் ஒளிரவில்லை.',
        '0.32': 'அவள் ஐயத்தால் மங்கிய நினைவு போலவும், வீழ்ந்த செல்வம் போலவும், சிதைந்த நம்பிக்கை போலவும், தடைபட்ட ஆசை போலவும் இருந்தாள்,',
        '0.33': 'இடையூறுகள் சூழ்ந்த வெற்றி போலவும், கலங்கிய அறிவு போலவும், பொய்ப் பழியால் வீழ்ந்த புகழ் போலவும்;',
        '0.34': 'ராமனிடமிருந்து தடுத்துவைக்கப்பட்ட வேதனையுடன், அரக்கியரால் துன்புறுத்தப்பட்டு, அபலையாய், மான்குட்டிக் கண்களுடன் அங்குமிங்கும் நோக்கியபடி,',
        '0.35': 'கண்ணீர் நிறைந்த, கருமையான வளைந்த இமைமயிர்கள் கொண்ட, ஒளியிழந்த முகத்துடன் அவள் மீண்டும் மீண்டும் பெருமூச்செறிந்தாள்.',
        '0.36': 'அழுக்கும் சேறும் படிந்து, துயருற்று, அணிகலன்களுக்கு உரியவளாயினும் அணியின்றி, கருமேகங்களால் மறைக்கப்பட்ட நிலவொளி போல அவள் இருந்தாள்.',
        '0.37': 'அந்நிலையில் சீதையைக் கண்டு, பயிற்சியின்றித் தளர்ந்த கல்வி போல அவன் அறிவு ஐயத்தில் ஆழ்ந்தது.',
        '0.38': 'செம்மையின்றி வேறு பொருள் கொண்ட சொல் போல, அணியற்ற சீதையை ஹனுமான் சிரமத்துடன் அடையாளம் கண்டான்.',
        '0.39': 'அந்தப் பெருங்கண்ணுடைய, பழியற்ற அரசகுமாரியைக் கூர்ந்து நோக்கி, சான்றுகளைக் கொண்டு அவளே சீதை என்று தர்க்கித்தான்.',
        '0.40': 'அன்று ராமன் வைதேகியின் அங்கங்களில் இருந்ததாக வர்ணித்த, உடலுக்கு அழகு தரும் அணிகலன்களை அவன் கவனித்தான்:',
        '0.41': 'நன்கு செய்யப்பட்ட காதணிகளும், சரியாக அமைந்த ஸ்வதம்ஷ்ட்ரக் குண்டலங்களும், கைகளில் மணி, பவளங்களால் அழகான அணிகலன்களும்.',
        '0.42': '“நீண்ட காலம் அணிந்ததால் கருத்திருந்தாலும் வடிவம் மாறாத இவையே ராமன் வர்ணித்தவை என்று எண்ணுகிறேன்.”',
        '0.43': '“அவள் கீழே விட்டெறிந்தவை இங்கே காணப்படவில்லை; விடாமல் வைத்திருப்பவை இவையே, ஐயமில்லை.”',
        '0.44': '“பொற்பட்டை போல் ஒளிர்ந்த, நழுவி விழுந்து மலையில் சிக்கிய அந்த அழகிய மஞ்சள் மேலாடையை அன்று வானரர் கண்டனர்.”',
        '0.45': '“அவளே கீழே எறிந்த, ஒலியெழுப்பும் பெரிய முக்கிய அணிகலன்களும் தரையில் காணப்பட்டன.”',
        '0.46': '“நீண்ட காலம் அணிந்ததால் இந்த ஆடை மிகவும் கசங்கியுள்ளது; ஆயினும் அதன் நிறம் அந்த மற்றொன்றைப் போலவே ஒளிமிக்கது.”',
        '0.47': '“பொன்னிற மேனியுடைய இவளே ராமனின் அன்புக்குரிய அரசி; தொலைந்துபோனாலும் அவன் மனத்திலிருந்து இவள் ஒருபோதும் மறையவில்லை.”',
        '0.48': '“இவளுக்காகவே ராமன் கருணை, இரக்கம், துயரம், காதல் ஆகிய நான்கினால் இங்கே வேதனைப்படுகிறான்.”',
        '0.49': '“ஒரு பெண் தொலைந்தாள் என்பதால் கருணை; தன்னை அண்டியவள் என்பதால் இரக்கம்; மனைவி பிரிந்தாள் என்பதால் துயரம்; அன்புக்குரியவள் என்பதால் காதல்.”',
        '0.50': '“இந்தத் தேவியின் அழகும் அங்கங்களின் எழிலும் ராமனின் வடிவுக்கு ஏற்றவை; இந்தக் கருவிழியாள் அவனுக்கே தக்கவள்.”',
        '0.51': '“இந்தத் தேவியின் மனம் அவனிடமும் அவன் மனம் இவளிடமும் நிலைத்துள்ளது; அதனால்தான் இவளும் அறவோனான ராமனும் கணநேரமாவது உயிர் வாழ்கின்றனர்.”',
        '0.52': '“இவளைப் பிரிந்தும் தலைவன் ராமன் தன் உடலைத் தாங்கித் துயரில் மூழ்காதிருப்பது உண்மையில் அரிய செயல்.”',
        '0.53': 'இவ்வாறு சீதையைக் கண்ட வாயுமைந்தன் மகிழ்ந்து, மனத்தாலேயே ராமனிடம் சென்று அந்தத் தலைவனைப் போற்றினான்.',
        '0.54': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் பதினைந்தாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-16': {
      verses: {
        '0.0': 'போற்றுதற்குரிய சீதையையும் குணங்களால் இனியவனான ராமனையும் புகழ்ந்த வானரச் சிறந்தோன் மீண்டும் சிந்தனையில் ஆழ்ந்தான்.',
        '0.1': 'சற்றுநேரம் சிந்தித்து, கண்ணீர் நிறைந்த கண்களுடன் ஒளிமிக்க ஹனுமான் சீதையைக் குறித்து இவ்வாறு புலம்பினான்:',
        '0.2': '“பெரியோரிடம் பணிவுடைய லக்ஷ்மணனுக்கு மதிப்புக்குரியவளும் அண்ணனுக்கு அன்பானவளுமான சீதையே இவ்வாறு துயருற்றால், காலத்தைக் கடப்பது உண்மையில் அரிது.”',
        '0.3': '“ராமனுடையவும் அறிவுடைய லக்ஷ்மணனுடையவும் உறுதியை அறிந்த தேவி, மழைக்காலம் வந்தபோதும் கலங்காத கங்கை போல மிகுதியாகக் கலங்குவதில்லை.”',
        '0.4': '“ஒழுக்கம், வயது, நடத்தை, குலம், இலக்கணங்களில் சமமான வைதேகிக்கு ராகவன் தக்கவன்; இந்தக் கருவிழியாள் அவனுக்குத் தக்கவள்.”',
        '0.5': 'புதுப் பொன்போல் ஒளிர்ந்த, உலகம் விரும்பும் திருமகள் போன்ற அவளைக் கண்டு, அவன் மனத்தாலேயே ராமனிடம் சென்று இவ்வாறு சொன்னான்:',
        '0.6': '“இந்தப் பெருங்கண்ணாளுக்காகவே பெருவலியனான வாலி கொல்லப்பட்டான்; வீரத்தில் ராவணனுக்கு நிகரான கபந்தனும் வீழ்த்தப்பட்டான்.”',
        '0.7': '“இந்திரன் சம்பரனைக் கொன்றது போல ராமன் காட்டில் வீரத்துடன் பயங்கர ஆற்றலுடைய அரக்கன் விராதனைப் போரில் கொன்றான்.”',
        '0.8': '“ஜனஸ்தானத்தில் தீக்கொழுந்து போன்ற அம்புகளால் கொடுஞ்செயல் புரியும் பதினான்காயிரம் அரக்கர் கொல்லப்பட்டனர்.”',
        '0.9': '“தன்னை அறிந்தவனான ராமனால் கரன் போரில் கொல்லப்பட்டான்; திரிசிரனும் பேராற்றலுடைய தூஷணனும் வீழ்த்தப்பட்டனர்.”',
        '0.10': '“இவள் காரணமாகவே உலகப் புகழ்பெற்ற சுக்ரீவன், வாலி காத்துவந்த அரிதான வானர அரசைப் பெற்றான்.”',
        '0.11': '“இந்தப் பெருங்கண்ணாளுக்காகவே ஆறுகளின் தலைவனான எழில்மிகு கடலை நான் கடந்தேன்; இந்த நகரையும் தேடினேன்.”',
        '0.12': '“இவளுக்காக ராமன் கடல் சூழ்ந்த பூமியையோ உலகம் முழுவதையோ புரட்டிப்போட்டாலும் அது தகுந்ததே என்பது என் கருத்து.”',
        '0.13': '“மூவுலக அரசா, ஜனகன் மகள் சீதையா — மூவுலக அரசு முழுவதும் சீதையின் ஒரு கூறுக்கும் ஈடாகாது.”',
        '0.14': '“இவளே அறநெறியுடைய மகாத்மா மிதிலை மன்னன் ஜனகனின் மகள், கணவனிடம் உறுதியான விரதம் பூண்ட சீதை;”',
        '0.15': '“கலப்பை நுனியால் உழப்பட்ட வயலில் பூமியைப் பிளந்து, தாமரை மகரந்தம் போன்ற மங்கலமான வயல் புழுதியால் மூடப்பட்டு எழுந்தவள்.”',
        '0.16': '“வீரனும் உயர்ந்த பண்புடையவனும் போரில் புறங்காட்டாதவனுமான தசரத மன்னனின் புகழ்மிக்க மூத்த மருமகள் இவள்.”',
        '0.17': '“அறம் அறிந்தவனும் நன்றியுடையவனும் தன்னை அறிந்தவனுமான ராமனின் அன்பு மனைவி இவள்; இப்போது அரக்கியரின் பிடியில் சிக்கியுள்ளாள்.”',
        '0.18': '“எல்லா இன்பங்களையும் துறந்து, கணவன்மேல் கொண்ட அன்பின் வலிமையால், துன்பங்களைப் பொருட்படுத்தாமல் அவள் ஆளில்லாக் காட்டுக்குள் புகுந்தாள்.”',
        '0.19': '“கனி, கிழங்குகளால் மனநிறைவுற்று, கணவனுக்குப் பணிவிடை செய்வதில் ஈடுபட்டு, அரண்மனையில் போலவே காட்டிலும் பேரின்பம் கண்டவள்.”',
        '0.20': '“பொன்னிற மேனியுடைய, எப்போதும் புன்னகையுடன் பேசும், துன்பங்களுக்குத் தகாத அவளே இந்த வேதனையைப் பொறுத்துக்கொண்டிருக்கிறாள்.”',
        '0.21': '“ராவணனால் துன்புறுத்தப்பட்ட இந்த ஒழுக்கமுடையவளைக் காண ராகவன், தாகமுற்றவன் தண்ணீர்ப் பந்தலை நாடுவது போல ஏங்குகிறான்.”',
        '0.22': '“இவளை மீண்டும் பெற்றதும் ராகவன், அரசிழந்த மன்னன் மீண்டும் பூமியைப் பெற்றது போல மகிழ்வான்.”',
        '0.23': '“இன்பங்களை இழந்து, உறவினரைப் பிரிந்து, அவனுடன் மீண்டும் சேரும் ஆசையால் மட்டுமே அவள் உடலைத் தாங்கியிருக்கிறாள்.”',
        '0.24': '“அவள் அரக்கியரையும் இந்தப் பூ, கனி மரங்களையும் பார்க்கவில்லை; ஒருமுகப்பட்ட இதயத்துடன் ராமனையே காண்கிறாள்.”',
        '0.25': '“கணவனே பெண்ணுக்கு அணிகலனை விடச் சிறந்த அழகு; அவனைப் பிரிந்த இவள் ஒளிர்வதற்கு உரியவளாயினும் ஒளிரவில்லை.”',
        '0.26': '“இவளைப் பிரிந்தும் தலைவன் ராமன் உடலைத் தாங்கித் துயரில் மூழ்காதிருப்பது அரிய செயல்.”',
        '0.27': '“கருங்கூந்தலும் நூறிதழ்த் தாமரை போன்ற கண்களும் கொண்ட, இன்பத்துக்குரிய இவள் துயருறுவதை அறிந்து என் மனமும் வருந்துகிறது.”',
        '0.28': '“பூமி போலப் பொறுமையுடையவள், தாமரைக் கண்ணாள், ராகவனாலும் லக்ஷ்மணனாலும் காக்கப்பட்டவள் — இப்போது மரத்தடியில் கோரக் கண்களுடைய அரக்கியரின் காவலில் இருக்கிறாள்.”',
        '0.29': '“பனியால் தாக்கப்பட்ட தாமரைக் குளம் போல எழில் இழந்து, அடுத்தடுத்த துன்பங்களால் நசுக்கப்பட்டு, துணையைப் பிரிந்த சக்ரவாகப் பெண்பறவை போல ஜனகன் மகள் பரிதாப நிலையை அடைந்துள்ளாள்.”',
        '0.30': '“மலர்களால் தாழ்ந்த கிளைநுனிகளுடைய அசோகங்கள் இவளுக்குக் கடுந்துயரையே தருகின்றன; பனி நீங்கியதும் உதித்த ஆயிரக்கணக்கான கதிர்களுடைய குளிர்நிலவும் அவ்வாறே.”',
        '0.31': 'இவ்வாறு ஆராய்ந்து இவளே சீதை என்று உறுதிகொண்ட வலிமையும் வேகமும் உடைய வானரச் சிறந்தோன் அந்த மரத்திலேயே அமர்ந்திருந்தான்.',
        '0.32': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் பதினாறாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-17': {
      verses: {
        '0.0': 'அப்போது அல்லிக் கூட்டம் போல் வெண்மையாக, தூய்மையாக உதித்த நிலவு, நீல நீரில் அன்னம் செல்வது போலத் தெளிந்த வானில் சென்றது.',
        '0.1': 'தன் ஒளியால் உதவுவது போலத் தெளிந்த ஒளியுடைய நிலவு குளிர்ந்த கதிர்களால் வாயுமைந்தனுக்குப் பணிவிடை செய்தது.',
        '0.2': 'அப்போது அவன் முழுநிலவு முகமுடைய சீதையைக் கண்டான்; சுமையால் நீரில் அமிழும் படகு போல அவள் துயரச் சுமையால் அழுந்தியிருந்தாள்.',
        '0.3': 'வைதேகியைக் காண விரும்பிய வாயுமைந்தன் ஹனுமான் அவளருகே கோரத் தோற்றமுடைய அரக்கியரைக் கண்டான்:',
        '0.4': 'ஒற்றைக் கண்ணுடையவள், ஒற்றைக் காதுடையவள், காதுகளாலேயே உடலை மூடியவள், காதில்லாதவள், ஆணி போன்ற காதுடையவள், உச்சியில் நாசித்துளைகள் உடையவள்;',
        '0.5': 'பெருந்தலையுடையவள், மெல்லிய நீண்ட கழுத்துடையவள், கலைந்த கூந்தலுடையவள், மயிரற்றவள், மயிரையே கம்பளம் போலப் போர்த்தியவள்;',
        '0.6': 'தொங்கும் காதும் நெற்றியும் உடையவள், தொங்கும் வயிறும் மார்பும் உடையவள், தொங்கும் உதடுடையவள், மோவாயில் உதடுடையவள், நீண்ட முகமுடையவள், நீண்ட முழங்காலுடையவள்;',
        '0.7': 'குள்ளமானவர், உயரமானவர், கூனர், விகாரமானவர், குறளர், கோரமானவர், கோணல் முகத்தவர், பழுப்புக் கண்ணர், உருக்குலைந்த முகத்தவர்;',
        '0.8': 'விகாரமானவர், பழுப்பும் கருப்பும் ஆனவர், சினமுடையவர், சண்டைப் பிரியர், கருப்பு இரும்பாலான பெரும் சூலம், கூடம், சம்மட்டி ஏந்தியவர்;',
        '0.9': 'சிலர் பன்றி, மான், புலி, எருமை, ஆடு, நரி முகத்தவர்; சிலர் யானை, ஒட்டகம், குதிரைக் கால்களுடையவர்; வேறு சிலர் உடலுக்குள் புதைந்த தலையுடையவர்;',
        '0.10': 'சிலர் ஒரு கை ஒரு காலுடையவர், சிலர் கழுதை, குதிரைக் காதுடையவர், சிலர் பசு, யானை, குரங்குக் காதுடையவர்;',
        '0.11': 'சிலர் பெரிய மூக்குடையவர், சிலர் கோணல் மூக்குடையவர், சிலர் மூக்கில்லாதவர், சிலர் யானைத் துதிக்கை போன்ற மூக்குடையவர், சிலர் நெற்றியில் நாசித்துளையுடையவர்;',
        '0.12': 'யானைக் கால், பெருங்கால், பசுக் கால், காலில் மயிர்க்கொத்து உடையவர்; மிகப் பெரிய தலையும் கழுத்தும், மிகப் பெரிய மார்பும் வயிறும் உடையவர்;',
        '0.13': 'மிகப் பெரிய வாயும் கண்ணும், நீண்ட நாக்கும் முகமும் உடையவர்; ஆடு, யானை, பசு, பெண்பன்றி முகத்தவர்;',
        '0.14': 'குதிரை, ஒட்டகம், கழுதை முகத்துடன், கைகளில் சூலமும் சம்மட்டியும் ஏந்திய, சினமும் சண்டைப் பிரியமும் கொண்ட கோர அரக்கியர்;',
        '0.15': 'கோரமும் புகைநிறக் கூந்தலும் உருக்குலைந்த முகமும் கொண்ட அரக்கியர் எப்போதும் மது அருந்தி, கள்ளையும் இறைச்சியையும் எப்போதும் விரும்புபவர்;',
        '0.16': 'இறைச்சியும் குருதியும் பூசிய உடலுடன், இறைச்சியையும் குருதியையும் உண்ணும், மயிர்க்கூச்செறியச் செய்யும் தோற்றமுடைய அவர்களை வானரச் சிறந்தோன் கண்டான்.',
        '0.17': 'அவர்கள் பரந்த கிளைகளுடைய பெருமரத்தைச் சூழ்ந்து அமர்ந்திருந்தனர்; அதன் கீழே பழியற்ற அரசகுமாரியான தேவி இருந்தாள் —',
        '0.18': 'எழில்மிக்க ஹனுமான் அங்கே ஒளியிழந்து, துயரால் வெந்து, அழுக்கடைந்த கூந்தலுடைய ஜனகன் மகளைக் கவனித்தான்,',
        '0.19': 'புண்ணியம் தீர்ந்து பூமியில் விழுந்த விண்மீன் போல, ஒழுக்கப் புகழ் நிறைந்தும் கணவனைக் காண இயலாத அவலநிலையில் இருந்தவளை;',
        '0.20': 'சிறந்த அணிகலன்கள் இன்றி, கணவன் அன்பையே அணியாகக் கொண்டு, அரக்கர் வேந்தனால் சிறைப்பட்டு, உறவினரைப் பிரிந்தவளை;',
        '0.21': 'மந்தையைப் பிரிந்து சிங்கத்தால் தடுக்கப்பட்டுக் கட்டுண்ட பெண்யானை போலவும், மழைக்கால முடிவில் கூதிர்கால மேகங்களால் மறைந்த பிறைநிலவு போலவும்;',
        '0.22': 'கணவனின் தொடுகை இல்லாததால் சுருதி சேர்க்காத வீணை போல் வாடிய அழகுடன், கணவன் நலனில் ஈடுபட்டு, அரக்கர் பிடிக்குத் தகாதவளை;',
        '0.23': 'அசோகவனத்தின் நடுவில் துயரக் கடலில் மூழ்கி, அப்பெண்களால் சூழப்பட்டுக் கோளால் பீடிக்கப்பட்ட ரோகிணி போல இருந்தவளை,',
        '0.24': 'பூவற்ற கொடி போல ஹனுமான் கண்டான். அழுக்குப் படிந்த அங்கங்களுடனும் உடலழகால் அணிசெய்யப்பட்ட அவள், சேறு பூசிய தாமரைத் தண்டு போல ஒளிர்ந்தும் ஒளிராமலும் இருந்தாள்.',
        '0.25': 'அழுக்கடைந்து நைந்த ஆடையால் போர்த்தப்பட்ட மான்குட்டிக் கண்ணுடைய அந்த அழகியை வானரன் ஹனுமான் கண்டான்.',
        '0.26': 'முகம் வாடியிருந்தும் கணவனின் ஆற்றலால் மனம் தளராத, தன் ஒழுக்கத்தாலேயே காக்கப்பட்ட கருவிழியாளான அந்தச் சீதா தேவியை —',
        '0.27': 'அஞ்சிய மான்குட்டி போலச் சுற்றிலும் நோக்கிய, மான்குட்டிக் கண்ணுடைய அந்தச் சீதையைக் கண்டு ஹனுமான்,',
        '0.28': 'பெருமூச்சுகளால் தளிர்நிறைந்த மரங்களை எரிப்பது போல, துயரங்களின் குவியல் போல, எழுந்த துன்ப அலை போல இருந்தவளை,',
        '0.29': 'பூமி போலப் பொறுமையும், சீரான அங்கங்களும் கொண்டு, அணிகலனின்றியும் அழகாகத் திகழ்ந்த மைதிலியைக் கண்டு மாருதி ஒப்பற்ற மகிழ்ச்சி அடைந்தான்.',
        '0.30': 'மயக்கும் கண்களுடைய அவளைக் கண்டு ஹனுமான் அங்கே ஆனந்தக் கண்ணீர் சொரிந்து ராகவனை வணங்கினான்.',
        '0.31': 'ராமனையும் லக்ஷ்மணனையும் வணங்கி, சீதையைக் கண்ட மகிழ்ச்சியுடன் வீரனான ஹனுமான் மறைந்தே இருந்தான்.',
        '0.32': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் பதினேழாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-18': {
      verses: {
        '0.0': 'பூத்த மரங்களுடைய சோலையை இவ்வாறு நோக்கி வைதேகியைத் தேடிக்கொண்டிருக்கையில் இரவு சிறிதே எஞ்சியிருந்தது.',
        '0.1': 'இரவின் இறுதி யாமத்தில் ஆறு அங்கங்களுடன் வேதங்களை அறிந்த, சிறந்த வேள்விகள் புரியும் பிரம்மராட்சசர்களின் வேத ஒலியை அவன் கேட்டான்.',
        '0.2': 'அப்போது செவிக்கும் மனத்துக்கும் இனிய மங்கல இசைக்கருவிகளின் ஒலியால் நீண்ட கைகளும் பெருவலிமையும் உடைய பத்துத்தலையன் எழுப்பப்பட்டான்.',
        '0.3': 'விழித்தெழுந்த பெரும்பேறுடைய, வீரமிக்க அரக்கர் வேந்தன் நழுவிய மாலையும் ஆடையுமாக வைதேகியையே நினைத்தான்.',
        '0.4': 'அவள் மீதான காமத்தால் கடுமையாகத் தூண்டப்பட்டு மதம் கொண்ட அந்த அரக்கன் அந்த ஆசையைத் தன்னுள் மறைக்க இயலவில்லை.',
        '0.5': 'எல்லா அணிகலன்களும் பூண்டு ஒப்பற்ற எழிலுடன் அவன் — எல்லாப் பூ, கனிகளும் நிறைந்த பலவகை மரங்கள் கொண்ட,',
        '0.6': 'தாமரைக் குளங்களால் சூழப்பட்டு, பலவகை மலர்களால் அழகுபெற்று, எப்போதும் களிப்புற்ற அற்புதப் பறவைகளால் வண்ணமயமான,',
        '0.7': 'கண்ணுக்கினிய பலவகை விலங்கு உருவங்கள் நிறைந்த, மணி, பொன் தோரணங்கள் கொண்ட அதன் வீதிகளை நோக்கியபடி,',
        '0.8': '— பலவகை மான் கூட்டங்கள் நிறைந்து, உதிர்ந்த கனிகளால் மூடப்பட்ட, அடர்ந்த மரங்களுடைய அசோகவனத்துக்குள்ளேயே நுழைந்தான்.',
        '0.9': 'தேவ, கந்தர்வப் பெண்கள் இந்திரனைப் பின்தொடர்வது போல ஏறக்குறைய நூறு பெண்கள் செல்லும் அந்தப் புலஸ்திய வம்சத்தவனைப் பின்தொடர்ந்தனர்.',
        '0.10': 'சில பெண்கள் பொன் விளக்குகளை ஏந்தினர்; சிலர் சாமரங்களையும் வேறு சிலர் பனையோலை விசிறிகளையும் ஏந்தினர்.',
        '0.11': 'சிலர் பொற்கெண்டிகளில் நீர் ஏந்தி முன்னே சென்றனர்; மற்றவர் வட்டத் திண்டுகளையும் இருக்கைகளையும் ஏந்திப் பின்னே சென்றனர்.',
        '0.12': 'திறமையான ஒருத்தி தன் வலக்கையில் மது நிறைந்த ஒளிரும் ரத்தினக் கிண்ணத்தை ஏந்தினாள்.',
        '0.13': 'மற்றொருத்தி அரச அன்னம் போல் வெண்மையான, முழுநிலவு போல் ஒளிரும், பொற்காம்புடைய குடையைப் பிடித்துப் பின்னே சென்றாள்.',
        '0.14': 'தூக்கமும் மயக்கமும் சூழ்ந்த கண்களுடைய ராவணனின் சிறந்த மனைவியர், மேகத்தை மின்னல்கள் தொடர்வது போல வீரக் கணவனைப் பின்தொடர்ந்தனர்.',
        '0.15': 'அவர்களின் மாலைகளும் தோள்வளைகளும் நிலைகுலைந்திருந்தன, பூச்சுகள் அழிந்திருந்தன, கூந்தல் நுனிகள் அவிழ்ந்திருந்தன, முகங்களில் வியர்வை இருந்தது,',
        '0.16': 'எஞ்சிய மயக்கத்தாலும் தூக்கத்தாலும் தள்ளாடிய அந்த அழகிய முகத்தவரின் அங்கங்களிலிருந்த மலர்கள் வியர்வையால் வாடியிருந்தன, கூந்தல் மாலைகளால் சிக்குண்டிருந்தது,',
        '0.17': '— மதுவால் ஒளிரும் கண்களுடைய அந்த அன்பு மனைவியர் பெருமதிப்பாலும் காமத்தாலும் செல்லும் அரக்கர் தலைவனைப் பின்தொடர்ந்தனர்.',
        '0.18': 'காமத்துக்கு அடிமையாகி, சீதையிடமே மனம் பற்றிய அந்த மூடனான அவர்களின் பெருவலிமைக் கணவன் மெதுவான அழகிய நடையுடன் விளங்கினான்.',
        '0.19': 'அப்போது வாயுமைந்தனான வானரன் அந்தச் சிறந்த பெண்களின் ஒட்டியாணங்களின் ஒலியையும் சிலம்புகளின் ஓசையையும் கேட்டான்.',
        '0.20': 'ஒப்பற்ற செயல்களும் எண்ணற்கரிய வலிமையும் ஆண்மையும் கொண்ட அவன் வாயிலுக்கு வந்ததை வானரன் ஹனுமான் கண்டான்.',
        '0.21': 'முன்னே ஏந்திச் செல்லப்பட்ட நறுமண எண்ணெய் நிறைந்த பல விளக்குகளால் அவன் சுற்றிலும் ஒளிர்ந்தான்.',
        '0.22': 'காமமும் செருக்கும் மயக்கமும் கொண்டு, ஓரக்கண்ணும் செம்பு நிறமும் நீளமும் உடைய கண்களுடன், வில்லைக் கீழே வைத்த நேரடி மன்மதன் போல் இருந்தான்.',
        '0.23': 'கடைந்த அமுதின் நுரை போல் வெண்மையான, களங்கமற்ற சிறந்த ஆடை மலர்களுடன் நழுவித் தோள்வளையில் சிக்கியிருக்க, அதை இழுத்தபடி அவன் வந்தான்.',
        '0.24': 'இலைக்கிளைகளில் மறைந்து, நூற்றுக்கணக்கான இலை, மலர்களால் மூடப்பட்டிருந்த ஹனுமான் அருகே வந்த அவனை அடையாளம் காண முயன்றான்.',
        '0.25': 'கூர்ந்து நோக்கிய வானர வேழம் அப்போது அழகும் இளமையும் நிறைந்த ராவணனின் சிறந்த மனைவியரைக் கண்டான்.',
        '0.26': 'அந்த அழகியரால் சூழப்பட்ட பெரும்புகழ் மன்னன் விலங்கு பறவைகளின் ஒலியால் எதிரொலிக்கும் அந்த மகளிர் சோலைக்குள் நுழைந்தான்.',
        '0.27': 'மது மயக்கமும் அற்புத அணிகலன்களும் கூர்மையான காதுகளும் கொண்ட பெருவலியனான விஸ்ரவஸின் மைந்தன் அரக்கர் தலைவனை அவன் கண்டான்.',
        '0.28': 'விண்மீன்களால் சூழப்பட்ட நிலவு போலச் சிறந்த பெண்களால் சூழப்பட்ட அந்த ஒளியுடையவனைப் பேரொளியுடைய மாபெரும் வானரன் கண்டான்.',
        '0.29': '“இவனே நீண்ட கைகளுடைய ராவணன்; முன்பு நகர் நடுவேயுள்ள சிறந்த மாளிகையில் உறங்கியவன் இவனே” என்று எண்ணிப் பேரொளியுடைய வாயுமைந்தன் ஹனுமான் சற்றுக் கீழே இறங்கினான்.',
        '0.30': 'தானே கடும் ஒளியுடையவனாயினும் ராவணனின் ஒளியால் அடக்கப்பட்ட அந்த அறிவாளி இலை மறைவுக்குள் ஒட்டிக்கொண்டு மறைந்திருந்தான்.',
        '0.31': 'கருங்கூந்தலும் அழகிய இடையும் நெருங்கிய மார்பகங்களும் கருத்த கடைக்கண்களும் உடைய அவளைக் காணும் ஆவலுடன் ராவணன் அருகே வந்தான்.',
        '0.32': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் பதினெட்டாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-19': {
      verses: {
        '0.0': 'அதே நேரத்தில் பழியற்ற அரசகுமாரி அழகும் இளமையும் நிறைந்த, சிறந்த அணிகலன்கள் பூண்ட அவனைக் கண்டாள்.',
        '0.1': 'அரக்கர் தலைவன் ராவணனைக் கண்டதுமே அழகிய வைதேகி புயல்காற்றில் வாழைமரம் போல நடுங்கினாள்.',
        '0.2': 'தொடைகளால் வயிற்றையும் கைகளால் மார்பையும் மறைத்துக்கொண்டு அந்தப் பெருங்கண்ணழகி அழுதபடி அமர்ந்தாள்.',
        '0.3': 'அரக்கியர் கூட்டங்களால் காக்கப்பட்டு, துயருற்று, வேதனையில் வாடி, கடலில் அமிழும் படகு போல இருந்த வைதேகியைப் பத்துத்தலையன் கண்டான்,',
        '0.4': 'விரிப்பில்லாத தரையில் அமர்ந்து, உறுதியான விரதம் பூண்டு, வெட்டப்பட்டு மண்ணில் விழுந்த பெருமரக் கிளை போல இருந்தவளை,',
        '0.5': 'அழுக்கையே அணியாகப் பூசிய அங்கங்களுடன், அணிகலனுக்குரியவளாயினும் அணியின்றி, சேறு பூசிய தாமரைத் தண்டு போல ஒளிர்ந்தும் ஒளிராமலும் இருந்தவளை,',
        '0.6': 'தன்னை அறிந்தவனான மன்னர் சிங்கம் ராமனிடம், உறுதியெனும் குதிரைகள் பூட்டிய ஆசைத் தேர்களில் செல்வது போல இருந்தவளை;',
        '0.7': 'வாடியபடி, அழுதபடி, தனியளாய், சிந்தனையிலும் துயரிலும் மூழ்கி, துன்பத்துக்கு முடிவு காணாத, ராமனிடமே பற்றுடைய அந்த அழகியை;',
        '0.8': 'மந்திரத்தால் கட்டுண்ட நாகராஜன் மனைவி போலத் துடித்தவளும், தூமகேதுவால் புகைசூழப்பட்ட ரோகிணி போன்றவளுமானவளை;',
        '0.9': 'நல்லொழுக்கமும் அறமும் கொண்ட குலத்தில் பிறந்திருந்தும், இப்போதைய நிலையால் தாழ்ந்த குலத்தில் பிறந்தவள் போலத் தோன்றியவளை;',
        '0.10': 'தாழ்ந்த பெரும்புகழ் போல, அவமதிக்கப்பட்ட நம்பிக்கை போல, தேய்ந்த அறிவு போல, தடைபட்ட ஆசை போல,',
        '0.11': 'அழிந்த எதிர்காலம் போல, மீறப்பட்ட ஆணை போல, அழிவுக்காலத்தில் எரியும் திசை போல, தடைபட்ட வழிபாடு போல,',
        '0.12': 'நிலவை இருள் விழுங்கிய முழுநிலவு இரவு போல, சிதைந்த தாமரைக் குளம் போல, வீரர்கள் கொல்லப்பட்ட படை போல,',
        '0.13': 'இருளால் அழிந்த ஒளி போல, வற்றிய ஆறு போல, தீட்டுப்பட்ட வேள்வி மேடை போல, அணைந்த தீக்கொழுந்து போல,',
        '0.14': 'இலைகளும் தாமரைகளும் பிடுங்கப்பட்டு, பறவைகள் அஞ்சி ஓட, யானைத் துதிக்கையால் கலக்கப்பட்ட தாமரைக் குளம் போலக் கலங்கியவளை;',
        '0.15': 'கணவன் பிரிவுத் துயரால் வாடி, நீர் வடிக்கப்பட்ட ஆறு போல வறண்டு, தேய்பிறை இரவு போலத் தூய்மையும் அலங்காரமும் இழந்தவளை;',
        '0.16': 'மென்மையானவள், அழகிய அங்கங்கள் உடையவள், ரத்தின உள்மாளிகைக்குத் தகுந்தவள், அப்போதுதான் பிடுங்கிய தாமரைத் தண்டு வெயிலில் வாடுவது போல வாடியவளை;',
        '0.17': 'பிடிக்கப்பட்டுத் தூணில் கட்டப்பட்டு, மந்தைத் தலைவனைப் பிரிந்து, கடுந்துயரில் பெருமூச்செறியும் யானையரசனின் துணைவி போல இருந்தவளை;',
        '0.18': 'ஒற்றை நீண்ட சடையால் முயற்சியின்றியே அழகுற்று, மழைக்கால முடிவில் கருநீலக் காட்டு வரிசை கொண்ட பூமி போல இருந்தவளை;',
        '0.19': 'உண்ணாமை, துயரம், சிந்தனை, அச்சம் ஆகியவற்றால் தேய்ந்து, மெலிந்து, வாடி, சிறிதே உண்டு, தவத்தையே செல்வமாகக் கொண்டவளை;',
        '0.20': 'துயரில் வாடி, தெய்வத்தின் முன் கைகூப்புவது போல, ரகு குலத் தலைவனின் ஆற்றலால் பத்துத்தலையனின் தோல்வியை மனத்தில் வேண்டியவளை;',
        '0.21': 'சுற்றிலும் நோக்கி அழுதவளும், அழகிய இமைகளும் செவ்வோரமுடைய நீண்ட வெண்கண்களும் கொண்டவளும், ராமனிடம் மிகுந்த பற்றுடையவளுமான பழியற்ற மைதிலியை ராவணன் தன் அழிவுக்காகவே மயக்க முயன்றான்.',
        '0.22': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் பத்தொன்பதாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-20': {
      verses: {
        '0.0': 'சூழப்பட்டு, துயருற்று, மகிழ்ச்சியிழந்த அந்தத் தவமங்கையிடம் ராவணன் பாவனைகள் நிறைந்த இனிய சொற்களால் தன் எண்ணத்தை வெளிப்படுத்தினான்.',
        '0.1': '“யானைத் துதிக்கை போன்ற தொடையுடையவளே, என்னைக் கண்டு மார்பையும் வயிற்றையும் மறைத்து, அச்சத்தால் உன்னையே கண்ணுக்குப் புலப்படாதவளாக்க விரும்புகிறாய் போலும்.”',
        '0.2': '“பெருங்கண்ணாளே, நான் உன்னை விரும்புகிறேன்; அன்பே, என்னை மதித்திடு. அங்கமெல்லாம் அழகுடையவளே, உலகங்களின் மனம் கவர்பவளே!”',
        '0.3': '“இங்கே மனிதர்களோ விரும்பிய உருவெடுக்கும் அரக்கர்களோ யாருமில்லை; சீதையே, என்னால் எழுந்த உன் அச்சத்தை விட்டுவிடு.”',
        '0.4': '“அஞ்சுபவளே, பிறர் மனைவியரை நாடுவதோ வலிந்து கவர்வதோ எப்போதும் அரக்கர்களின் சுயதர்மமே, ஐயமில்லை.”',
        '0.5': '“அப்படியிருந்தும் மைதிலியே, நீ விரும்பாதவரை உன்னைத் தொடமாட்டேன்; காமம் என் உடலில் விரும்பியபடி செயல்படட்டும்.”',
        '0.6': '“தேவியே, இங்கே அஞ்ச வேண்டாம்; அன்பே, என்னை நம்பு. உண்மையாக அன்பு காட்டு; இவ்வாறு துயரில் மூழ்காதே.”',
        '0.7': '“ஒற்றைச் சடை, தரையில் படுத்தல், சிந்தனை, அழுக்கு ஆடை, தேவையற்ற உண்ணாநோன்பு — இவை உனக்கு ஏற்றவையல்ல.”',
        '0.8': '“அற்புத மாலைகள், சந்தனம், அகில், பலவகை ஆடைகள், தெய்வீக அணிகலன்கள்,”',
        '0.9': '“விலையுயர்ந்த பானங்கள், படுக்கைகள், இருக்கைகள், பாட்டு, நடனம், இசை — மைதிலியே, என்னை அடைந்தால் இவை அனைத்தையும் பெறுவாய்.”',
        '0.10': '“நீ பெண்களில் ரத்தினம்; இப்படி இருக்காதே. அங்கங்களில் அணிகலன்களைப் பூணு. அழகியே, என்னை அடைந்தபின் உனக்குரியவற்றை நீ எப்படி இழப்பாய்?”',
        '0.11': '“உன்னிடம் மலர்ந்துள்ள இந்த அழகிய இளமை கடந்துபோகிறது; ஆற்றின் ஓட்டம் போலக் கடந்தது மீண்டும் வராது.”',
        '0.12': '“உருவங்களைப் படைக்கும் அந்த உலகப் படைப்பாளன் உன்னைப் படைத்தபின் நிறுத்திவிட்டான் என்று எண்ணுகிறேன்; அழகியே, உன் அழகுக்கு இணை வேறொருத்தி இல்லை.”',
        '0.13': '“வைதேகியே, அழகும் இளமையும் நிறைந்த உன்னை நெருங்கியபின் நேரடிப் பிரம்மாவே ஆனாலும் யார்தான் எல்லை மீறாமல் இருப்பார்?”',
        '0.14': '“நிலவு முகத்தவளே, அகன்ற இடையாளே, உன் எந்த அங்கத்தைப் பார்க்கிறேனோ அங்கேயே என் கண் கட்டுண்டு நிற்கிறது.”',
        '0.15': '“மைதிலியே, என் மனைவியாகு; இந்த மயக்கத்தை விடு. என் பல சிறந்த மனைவியரில் நீயே பட்டத்தரசியாகு.”',
        '0.16': '“அஞ்சுபவளே, உலகங்களிலிருந்து வலிந்து கொண்டுவந்த ரத்தினங்கள் அனைத்தையும் என் அரசையும் உனக்குத் தருகிறேன்.”',
        '0.17': '“எழிலியே, பல நகரங்களை மாலையாகக் கொண்ட பூமி முழுவதையும் வென்று உனக்காக ஜனகனுக்குத் தருவேன்.”',
        '0.18': '“வலிமையில் எனக்கு நிகரானவன் இவ்வுலகில் வேறு யாரையும் நான் காணவில்லை. போரில் எதிரற்ற என் பெரும் வீரத்தைப் பார்.”',
        '0.19': '“போரில் தேவர்களையும் அசுரர்களையும் மீண்டும் மீண்டும் முறியடித்து அவர்களின் கொடிகளை மிதித்துள்ளேன்; என் எதிரே அணிவகுப்பில் அவர்களால் நிற்க இயலாது.”',
        '0.20': '“என்னை ஏற்றுக்கொள்; இன்றே உனக்குச் சிறந்த ஒப்பனை செய்யப்படட்டும், ஒளிரும் அணிகலன்கள் உன் அங்கங்களில் பூட்டப்படட்டும்.”',
        '0.21': '“அழகிய முகத்தவளே, அன்பால் ஒப்பனை செய்துகொண்ட உன் அழகிய வடிவை நான் நன்கு காண விரும்புகிறேன்.”',
        '0.22': '“அஞ்சுபவளே, விரும்பியபடி இன்பங்களை அனுபவி, அருந்து, மகிழ்; விரும்பியவாறு பூமியையோ செல்வத்தையோ கொடையாக அளி.”',
        '0.23': '“நம்பிக்கையுடன் என்னுடன் களித்திரு, துணிவுடன் ஆணையிடு; என் அருளால் நீ களிப்பது போல உன் உறவினரும் களிக்கட்டும்.”',
        '0.24': '“மங்கலமானவளே, புகழுடையவளே, என் செல்வத்தையும் சிறப்பையும் பார்; நல்லவளே, மரவுரி அணிந்த ராமனால் உனக்கு என்ன ஆகப்போகிறது?”',
        '0.25': '“ராமன் வெற்றியைக் கைவிட்டவன், செல்வமிழந்தவன், காட்டில் திரிபவன், விரதம் பூண்டு வெறுந்தரையில் படுப்பவன்; அவன் உயிரோடிருக்கிறானோ இல்லையோ என்று ஐயுறுகிறேன்.”',
        '0.26': '“வைதேகியே, முன்னே கொக்குக் கூட்டங்கள் செல்லும் கருமேகங்களால் மறைந்த நிலவொளி போல, ராமனால் உன்னைக் காணக்கூட இயலாது.”',
        '0.27': '“இந்திரன் கைக்குச் சென்ற புகழை இரணியகசிபு மீட்க இயலாதது போல, ராகவனும் என் கையிலிருந்து உன்னைப் பெற இயலாது.”',
        '0.28': '“அழகிய புன்னகையும் அழகிய பற்களும் அழகிய கண்களும் உடைய எழிலியே, அஞ்சுபவளே, கருடன் பாம்பைக் கவர்வது போல நீ என் மனத்தைக் கவர்கிறாய்.”',
        '0.29': '“கசங்கிய பட்டாடையுடனும் அணிகலனின்றியும் இருக்கும் மெல்லியலாளான உன்னைக் கண்டபின் என் மனைவியரிடம் எனக்கு மகிழ்ச்சியே இல்லை.”',
        '0.30': '“ஜானகியே, எல்லா நற்குணங்களும் கொண்ட என் அந்தப்புரப் பெண்கள் எத்தனை பேர் உள்ளனரோ அவர்கள் அனைவர் மீதும் நீ தலைமை செலுத்து.”',
        '0.31': '“கருங்கூந்தலாளே, மூவுலகின் சிறந்த பெண்களான என் மனைவியர், அப்சரஸ்கள் திருமகளுக்குப் பணிவிடை செய்வது போல உனக்குப் பணிவிடை செய்வார்கள்.”',
        '0.32': '“அழகிய புருவத்தாளே, அழகிய இடையாளே, வைஸ்ரவணனின் (குபேரனின்) ரத்தினங்களையும் செல்வங்களையும் உலகங்களையும் என்னுடன் இன்பமாக அனுபவி.”',
        '0.33': '“தேவியே, தவம், வலிமை, வீரம், செல்வம், ஒளி, புகழ் — எதிலும் ராமன் எனக்கு நிகரல்லன்.”',
        '0.34': '“அருந்து, உலவு, மகிழ், இன்பங்களை அனுபவி; உனக்குச் செல்வக் குவியலையும் பூமியையும் தருவேன். அழகியே, என்னுடன் இன்பமாகக் களித்திரு; உன் உறவினரும் வந்து உன்னுடன் களிக்கட்டும்.”',
        '0.35': '“அஞ்சுபவளே, தூய பொன் மாலைகள் அணிந்து, பூத்த மரக்கூட்டங்கள் நிறைந்த, வண்டுகள் ரீங்கரிக்கும் கடற்கரைச் சோலைகளில் என்னுடன் உலவு.”',
        '0.36': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் இருபதாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-21': {
      verses: {
        '0.0': 'அந்தக் கொடிய அரக்கனின் சொற்களைக் கேட்டு வருந்திய சீதை துயரக் குரலில் மெல்லப் பதிலளித்தாள்.',
        '0.1': 'துயரில் வாடி அழுது நடுங்கிய அந்தக் கற்புடைய அழகி சீதை தன் கணவனையே நினைத்தாள்.',
        '0.2': 'இருவருக்குமிடையே ஒரு புல்லை வைத்துத் தூய புன்னகையாள் பதிலளித்தாள்: “உன் மனத்தை என்னிடமிருந்து திருப்பிக்கொள்; உன் மனைவியரிடமே உன் மனம் மகிழட்டும்.”',
        '0.3': '“பாவி சித்தியை நாடுவது தகாதது போல என்னை நாடுவது உனக்குத் தகாது. ஒருவனுக்கே உரிய நான் பழிக்கப்பட்ட தகாத செயலைச் செய்யமாட்டேன் —”',
        '0.4': '“— பெருங்குலத்தில் பிறந்து புனிதக் குலத்தை அடைந்தவள் நான்.” இவ்வாறு ராவணனிடம் கூறிப் புகழுடைய வைதேகி',
        '0.5': 'ராவணனுக்கு முதுகைக் காட்டி மீண்டும் சொன்னாள்: “பிறனுடைய கற்புள்ள மனைவியான நான் உனக்குத் தகுந்த மனைவியல்லள்.”',
        '0.6': '“அறத்தை நன்கு நோக்கு, நல்லோர் விரதத்தைக் கடைப்பிடி. இரவில் திரிபவனே, உன் மனைவியர் போலவே பிறர் மனைவியரும் காக்கப்பட வேண்டியவர்.”',
        '0.7': '“உன்னையே உவமையாகக் கொண்டு உன் மனைவியரிடமே மகிழ். தன் மனைவியரிடம் திருப்தியற்ற, அலையும் புலன்களுடைய, கோணல் புத்தியுடைய சஞ்சலனைப் பிறர் மனைவியர் அழிவுக்கு இட்டுச் செல்வர்.”',
        '0.8': '“இங்கே நல்லோர் இல்லையோ, அல்லது இருந்தும் நீ அவர்களைப் பின்பற்றவில்லையோ — ஒழுக்கமற்ற உன் புத்தி அவ்வளவு திரிந்துள்ளது.”',
        '0.9': '“அல்லது பொய்யிலேயே மனம் வைத்த நீ அறிவாளிகள் சொன்ன நல்லுரையை ஏற்பதில்லை — இது அரக்கர்களின் அழிவுக்கே.”',
        '0.10': '“அடக்கமற்ற, அநீதியில் மகிழும் மன்னனைப் பெற்ற செழிப்பான நாடுகளும் நகரங்களும் அழிகின்றன.”',
        '0.11': '“அதுபோலவே ரத்தினக் குவியல்கள் நிறைந்த இலங்கையும் உன்னைப் பெற்றதால் உன் ஒருவனின் குற்றத்தால் விரைவில் அழியும்.”',
        '0.12': '“ராவணா, தொலைநோக்கில்லாத பாவி தன் செயல்களாலேயே அழியும்போது அவன் அழிவில் எல்லா உயிர்களும் மகிழ்கின்றன.”',
        '0.13': '“அதுபோலவே உன்னால் அநீதிக்கு ஆளான மக்கள் பாவியான உன்னைப் பற்றி ‘நல்லவேளை, இந்தக் கொடியவனுக்கு இந்தக் கேடு வந்தது’ என்று மகிழ்ந்து சொல்வார்கள்.”',
        '0.14': '“அதிகாரத்தாலோ செல்வத்தாலோ என்னை மயக்க இயலாது. கதிரவனிடமிருந்து ஒளி பிரியாதது போல நான் ராகவனிடமிருந்து பிரியாதவள்.”',
        '0.15': '“உலகநாதனான அவனது மதிப்புக்குரிய தோளைத் தலையணையாகக் கொண்ட நான் வேறு ஒருவனின் தோளை எப்படித் தலையணையாக்குவேன்?”',
        '0.16': '“விரதம் முடித்த தன்னை அறிந்த அந்தணனுக்குக் கல்வி உரியது போல, நான் அந்தப் பூமிநாதனுக்கே உரிய மனைவி.”',
        '0.17': '“ராவணா, காட்டில் பெண்யானையை யானையரசனுடன் சேர்ப்பது போல, துயருற்ற என்னை ராமனுடன் சேர்ப்பது உனக்கு நல்லது.”',
        '0.18': '“உன் நிலையைக் காக்க விரும்பினால், கொடிய அழிவை விரும்பாவிட்டால், மனிதருள் சிறந்த ராமனை நண்பனாக்கிக்கொள்.”',
        '0.19': '“அவன் எல்லா அறங்களையும் அறிந்தவன், அடைக்கலம் புகுந்தோரிடம் அன்புடையவன் என்று புகழ்பெற்றவன். உயிர் வாழ விரும்பினால் அவனுடன் நட்புக்கொள்.”',
        '0.20': '“அடைக்கலம் புகுந்தோரிடம் அன்புடைய அவனை மகிழ்வி; பணிவுடன் என்னை அவனிடம் ஒப்படை.”',
        '0.21': '“ரகு குலத் தலைவனிடம் என்னை ஒப்படைத்தால் உனக்கு நலம் உண்டாகும்; வேறுவிதமாக நடந்தால் பெருங்கேட்டை அடைவாய்.”',
        '0.22': '“எறியப்பட்ட வஜ்ராயுதம் கூட உன் போன்றவனை விட்டுவிடலாம், யமன் கூட நீண்டகாலம் விட்டுவைக்கலாம்; ஆனால் சினமுற்ற உலகநாதன் ராகவன் விடமாட்டான்.”',
        '0.23': '“நூறு வேள்வி புரிந்த இந்திரன் எறிந்த இடியின் முழக்கம் போல ராமனின் வில்லின் பேரொலியை நீ கேட்பாய்.”',
        '0.24': '“இங்கே விரைவில் ராம லக்ஷ்மணர் பெயர் பொறித்த, நல்ல கணுக்களுடைய அம்புகள் எரியும் வாயுடைய பாம்புகள் போல வந்து விழும்.”',
        '0.25': '“இந்நகரில் அரக்கர்களைக் கொன்றபடி, கங்கப் பறவை இறகுடைய அந்த அம்புகள் இடைவிடாது விழுந்து எந்த இடத்தையும் விடாது, ஐயமில்லை.”',
        '0.26': '“வினதையின் மைந்தன் கருடன் பாம்புகளைப் பிடுங்குவது போல, ராமன் என்னும் மாபெரும் கருடன் அரக்கர் தலைவர்கள் என்னும் பெரும் பாம்புகளை விரைந்து பிடுங்கியெறிவான்.”',
        '0.27': '“விஷ்ணு மூன்றடிகளால் அசுரர்களிடமிருந்து ஒளிரும் செல்வத்தை மீட்டது போல, பகைவரை அடக்கும் என் கணவன் உன்னிடமிருந்து என்னை விரைவில் மீட்பான்.”',
        '0.28': '“ஜனஸ்தானத்தில் அரக்கர் படை அழிந்து அந்த இருப்பிடம் சிதைந்தபோது, அரக்கனே, இயலாதவனான நீ இந்தத் தீச்செயலைச் செய்தாய்.”',
        '0.29': '“இழிந்தவனே, மனிதருள் சிங்கமான அந்தச் சகோதரர் இருவரும் வெளியே சென்றிருந்தபோது அவர்களின் ஆளில்லா ஆசிரமத்தில் புகுந்து நீ என்னைக் கவர்ந்தாய்.”',
        '0.30': '“ராம லக்ஷ்மணரின் மணம் பட்டாலே போதும், இரு புலிகளின் முன் நாய் போல நீ அவர்கள் பார்வையில் நிற்க இயலாது.”',
        '0.31': '“அவர்கள் இருவருடன் போரிட்டால், இந்திரனின் இரு கைகளில் ஒன்றுடன் போரிட்ட விருத்திரன் போல, உன் பிடி நிலைக்காது.”',
        '0.32': '“கதிரவன் சிறிது நீரை உறிஞ்சுவது போல என் தலைவன் ராமன் சௌமித்ரியுடன் விரைவில் அம்புகளால் உன் உயிரைப் பறிப்பான்.”',
        '0.33': '“குபேரனின் மலைக்கோ அவன் இல்லத்துக்கோ வருண மன்னனின் அவைக்கோ சென்றாலும், காலம் முடிந்த பெருமரம் இடியிலிருந்து தப்பாதது போல, தசரதன் மைந்தனிடமிருந்து நீ நிச்சயம் தப்பமாட்டாய்.”',
        '0.34': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் இருபத்தொன்றாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-22': {
      verses: {
        '0.0': 'சீதையின் கடுஞ்சொற்களைக் கேட்டு அரக்கர் வேந்தன் அழகிய சீதைக்கு இனிமையற்ற பதில் சொன்னான்.',
        '0.1': '“பெண்களை எவ்வளவு சமாதானப்படுத்துகிறானோ அவ்வளவு அவர்களுக்கு அடங்குகிறான்; எவ்வளவு இனிமையாகப் பேசுகிறானோ அவ்வளவு அவமதிக்கப்படுகிறான்.”',
        '0.2': '“வழிதவறி ஓடும் குதிரைகளை நல்ல தேரோட்டி அடக்குவது போல, உன் மீது எழுந்த காமம் என் சினத்தை அடக்குகிறது.”',
        '0.3': '“மனிதரின் காமம் விந்தையானது; அது யாரிடம் கட்டுகிறதோ அவரிடம் இரக்கமும் பாசமும் பிறக்கின்றன.”',
        '0.4': '“இதனால்தான் அழகிய முகத்தவளே, போலித் துறவியிடம் பற்றுக்கொண்டு கொலைக்கும் அவமதிப்புக்கும் தகுந்தவளாயினும் உன்னைக் கொல்லச் செய்யவில்லை.”',
        '0.5': '“மைதிலியே, நீ என்னிடம் சொல்லும் ஒவ்வொரு கடுஞ்சொல்லுக்கும் உனக்குக் கொடிய மரணமே தகும்.”',
        '0.6': 'வைதேகியிடம் இவ்வாறு சொல்லிச் சினத்தின் வேகத்தில் அரக்கர் தலைவன் ராவணன் சீதையிடம் மேலும் சொன்னான்:',
        '0.7': '“நான் உனக்கு விதித்த கெடுவில் இரண்டு மாதங்கள் எஞ்சியுள்ளன; அதன்பின் அழகியே, நீ என் படுக்கைக்கு வரவேண்டும்.”',
        '0.8': '“இரண்டு மாதங்களுக்குப் பின்னும் என்னைக் கணவனாக ஏற்காவிட்டால் என் சமையல்காரர்கள் என் காலை உணவுக்காக உன்னைத் துண்டு துண்டாக வெட்டுவார்கள்.”',
        '0.9': 'அரக்கர் வேந்தன் ஜானகியை மிரட்டுவதைக் கண்டு அங்கிருந்த தேவ, கந்தர்வக் கன்னியர் கண்கள் கலங்கி வருந்தினர்.',
        '0.10': 'சிலர் உதட்டசைவுகளாலும், வேறு சிலர் கண்களாலும் முகங்களாலும், அந்த அரக்கனால் மிரட்டப்பட்ட சீதையைத் தேற்றினர்.',
        '0.11': 'அவர்களால் தேற்றப்பட்ட சீதை அரக்கர் தலைவன் ராவணனிடம் தன் ஒழுக்கமும் துணிவும் தந்த பெருமிதத்துடன், அவன் நலனுக்கான இச்சொற்களைச் சொன்னாள்:',
        '0.12': '“இந்தப் பழிக்கப்பட்ட செயலிலிருந்து உன்னைத் தடுக்கும், உன் நலம் நாடும் ஒருவரும் இங்கில்லை என்பது உறுதி.”',
        '0.13': '“இந்திரனின் மனைவி சசி போல அந்த அறவோனின் மனைவியான என்னை, மூவுலகிலும் உன்னைத் தவிர யார்தான் மனத்தால் கூட விரும்புவார்?”',
        '0.14': '“அரக்கருள் இழிந்தவனே, அளவற்ற ஒளியுடைய ராமனின் மனைவியிடம் நீ பேசிய பாவச் சொற்களின் பயனிலிருந்து எங்கே சென்று தப்புவாய்?”',
        '0.15': '“காட்டில் மதயானையும் முயலும் சேர்ந்திருப்பது போல, ராமன் யானை; இழிந்தவனே, நீ முயல் எனப்படுவாய்.”',
        '0.16': '“இக்ஷ்வாகு நாதனை இங்கே இகழ்ந்து நீ வெட்கப்படவில்லை — அவன் பார்வையில் படாத வரைதான்.”',
        '0.17': '“இழிந்தவனே, என்னைப் பார்க்கும்போது உன் இந்தக் கொடிய, விகாரமான, கரு-பழுப்புக் கண்கள் ஏன் தரையில் விழவில்லை?”',
        '0.18': '“பாவியே, அந்த அறவோனின் மனைவியும் தசரதனின் மருமகளுமான என்னிடம் பேசும்போது உன் நாக்கு ஏன் அழுகி விழவில்லை?”',
        '0.19': '“பத்துத்தலையனே, ராமனின் கட்டளை இல்லாததாலும் என் தவத்தைக் காப்பதற்காகவுமே, சாம்பலாக்க வல்ல என் ஆற்றலால் உன்னைச் சாம்பலாக்காமல் இருக்கிறேன்.”',
        '0.20': '“அறிவுடைய ராமனிடமிருந்து என்னைக் கவர்வது இயலாதது; உன் அழிவுக்காகவே விதி இதை அமைத்தது, ஐயமில்லை.”',
        '0.21': '“வீரனும் குபேரனின் சகோதரனும் படைபலம் மிக்கவனுமான நீ, ஏதோ சூழ்ச்சியால் ராமனை அப்புறப்படுத்தி மனைவியைத் திருடியது ஏன்?”',
        '0.22': 'சீதையின் சொற்களைக் கேட்டு அரக்கர் தலைவன் ராவணன் கொடிய கண்களை உருட்டி ஜானகியை முறைத்துப் பார்த்தான்.',
        '0.23': 'கருமேகம் போன்றவன், பெருங்கைகளும் கழுத்தும் உடையவன், சிங்கத்தின் வலிமையும் நடையும் கொண்டவன், எழிலுடையவன், எரியும் நாவும் கொடிய கண்களும் கொண்ட அவன்,',
        '0.24': 'அசையும் மகுடத்தால் உயர்ந்து தோன்றியவன், வண்ண மாலைகளும் பூச்சுகளும் கொண்டவன், சிவந்த மாலையும் ஆடையும் அணிந்தவன், புடமிட்ட பொன் தோள்வளைகள் பூண்டவன்,',
        '0.25': 'பெரிய கருநிற ஒட்டியாணத்தால் இறுகக் கட்டப்பட்ட அவன், அமுதம் கடைந்தபோது பாம்பால் சுற்றப்பட்ட மந்தர மலை போலத் தோன்றினான்.',
        '0.26': 'அந்த இரு பருத்த கைகளுடன் மலை போன்ற அரக்கர் வேந்தன் இரு சிகரங்களுடைய மந்தர மலை போல விளங்கினான்.',
        '0.27': 'இளங்கதிரவன் நிறக் குண்டலங்கள் பூண்ட அவன், சிவந்த தளிர்களும் மலர்களும் கொண்ட இரு அசோக மரங்களுடைய மலை போல இருந்தான்.',
        '0.28': 'கற்பக மரம் போலவும், உருவெடுத்த வசந்தம் போலவும் இருந்தும், அணிசெய்திருந்தும் சுடுகாட்டுக் கோயில் போல அச்சமூட்டினான்.',
        '0.29': 'சினத்தால் சிவந்த கண்களால் வைதேகியை நோக்கி, பாம்பு போலச் சீறியபடி ராவணன் சீதையிடம் சொன்னான்:',
        '0.30': '“நெறியற்றவனும் செல்வமற்றவனுமான ஒருவனிடம் பற்றுக்கொண்ட உன்னை, கதிரவன் தன் ஆற்றலால் அந்திமாலையை அழிப்பது போல இன்றே அழிப்பேன்.”',
        '0.31': 'மைதிலியிடம் இவ்வாறு சொல்லிப் பகைவரை அழச்செய்யும் மன்னன் ராவணன் கோரத் தோற்றமுடைய அரக்கியர் அனைவரையும் நோக்கினான்:',
        '0.32': 'ஒற்றைக் கண்ணாள், ஒற்றைக் காதாள், காதால் மூடியவள், பசுக் காதாள், யானைக் காதாள், நீண்ட காதாள், காதில்லாதவள்;',
        '0.33': 'யானைக் காலாள், குதிரைக் காலாள், பசுக் காலாள், காலில் மயிருடையவள், ஒற்றைக் கண்ணாள், ஒற்றைக் காலாள், அகன்ற காலாள், காலில்லாதவள்;',
        '0.34': 'மிகப் பெரிய தலையும் கழுத்தும் உடையவள், மிகப் பெரிய மார்பும் வயிறும் உடையவள், மிகப் பெரிய வாயும் கண்ணும் உடையவள், நீண்ட நாவும் நகமும் உடையவள்,',
        '0.35': 'மூக்கில்லாதவள், சிங்க முகத்தாள், பசு முகத்தாள், பன்றி முகத்தாள் — இவர்களிடம் சொன்னான்: “ஜனகன் மகள் சீதை விரைவில் எனக்கு வசப்படுமாறு,”',
        '0.36': '“அரக்கியரே, அனைவரும் விரைவில் தனித்தோ கூடியோ அவ்வாறு செய்யுங்கள் — கடுமையான, மென்மையான வழிகளாலும், சாம, தான, பேதங்களாலும்,”',
        '0.37': '“தண்டனையை உயர்த்தியும் வைதேகியை என் பக்கம் வளைய வையுங்கள்.” இவ்வாறு மீண்டும் மீண்டும் ஆணையிட்டு அரக்கர் வேந்தன்,',
        '0.38': 'காமமும் சினமும் சூழ ஜானகியை மிரட்டினான். அப்போது அரக்கி தான்யமாலினி விரைந்து அருகே வந்து,',
        '0.39': 'பத்துத்தலையனைத் தழுவிச் சொன்னாள்: “மகாராஜா, என்னுடன் விளையாடு; இந்தச் சீதையால் உனக்கு என்ன பயன்,”',
        '0.40': '“நிறமிழந்த, பரிதாபமான, வெறும் மானுடப் பெண்ணான இவளால், அரக்கர் வேந்தே? மகாராஜா, தேவர்கள் இவளுக்குச் சிறந்த இன்பங்களை விதிக்கவில்லை,”',
        '0.41': '“உன் தோள்வலியால் ஈட்டிய இன்பங்களை. விரும்பாத பெண்ணை நாடுபவனின் உடல் வெந்து போவது மட்டுமே.”',
        '0.42': '“விரும்புபவளை நாடுபவனுக்கு அழகிய இன்பம் கிடைக்கிறது.” அரக்கி இவ்வாறு சொல்லி இழுத்துச் செல்ல, மேகம் போன்ற அந்த வலிய அரக்கன் சிரித்தபடி திரும்பினான்.',
        '0.43': 'பத்துத்தலையன் பூமியையே நடுங்கச் செய்வது போலப் புறப்பட்டு, எரியும் கதிரவன் போல் ஒளிரும் தன் மாளிகைக்குள் நுழைந்தான்.',
        '0.44': 'அப்போது தேவ, கந்தர்வ, நாகக் கன்னியர் பத்துத்தலையனைச் சூழ்ந்து அந்தச் சிறந்த மாளிகைக்குள் நுழைந்தனர்.',
        '0.45': 'அறத்தில் உறுதியாக நின்று நடுங்கிய மைதிலியை மிரட்டிவிட்டு, காமத்தால் மயங்கிய ராவணன் சீதையை விட்டுத் தன் மாளிகைக்குள் சென்றான்.',
        '0.46': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் இருபத்திரண்டாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-23': {
      verses: {
        '0.0': 'மைதிலியிடம் இவ்வாறு சொல்லி, அரக்கியர் அனைவருக்கும் ஆணையிட்டு, பகைவரை அழச்செய்யும் மன்னன் ராவணன் வெளியேறினான்.',
        '0.1': 'அரக்கர் வேந்தன் சென்று அந்தப்புரத்துக்குத் திரும்பியதும் கோர உருவுடைய அந்த அரக்கியர் சீதையை நோக்கிப் பாய்ந்தனர்.',
        '0.2': 'சீதையிடம் வந்த சினத்தால் வெறிகொண்ட அரக்கியர் மிகக் கடுமையான சொற்களால் வைதேகியிடம் இவ்வாறு சொன்னார்கள்:',
        '0.3': '“சீதையே, புலஸ்திய வம்சத்தில் சிறந்தவனும் மகாத்மாவுமான பத்துத்தலை ராவணனின் மனைவியாவதை நீ பெரிதாக மதிக்கவில்லையே!”',
        '0.4': 'அப்போது ஏகஜடை என்னும் அரக்கி சினத்தால் செம்பு நிறக் கண்களுடன், உள்ளங்கை போன்ற இடையுடைய சீதையை விளித்துச் சொன்னாள்:',
        '0.5': '“ஆறு பிரஜாபதிகளில் நான்காமவர் பிரம்மாவின் மனத்தில் பிறந்த மைந்தரான புகழ்பெற்ற புலஸ்தியர்.”',
        '0.6': '“புலஸ்தியரின் மனத்தில் பிறந்த மைந்தர் பிரஜாபதிக்கு நிகரான ஒளியுடைய தேஜஸ்வியான மகரிஷி விஸ்ரவஸ்.”',
        '0.7': '“பெருங்கண்ணாளே, அவர் மைந்தனே பகைவரை அழச்செய்யும் ராவணன்; அந்த அரக்கர் வேந்தனின் மனைவியாக நீ ஆகவேண்டும்.”',
        '0.8': '“அங்கமெல்லாம் அழகியவளே, நான் சொன்னதை ஏன் ஏற்கவில்லை?” அப்போது ஹரிஜடை என்னும் அரக்கி சொன்னாள்,',
        '0.9': 'சினத்தால் பூனை போன்ற கண்களை உருட்டியபடி: “முப்பத்து மூன்று தேவர்களையும் தேவராஜனையும் வென்றவன் யாரோ —”',
        '0.10': '“அந்த அரக்கர் வேந்தனின் மனைவியாக நீ தகுந்தவள். வீரத்தால் செருக்குடைய, போரில் புறங்காட்டாத, வலிமையும் ஆற்றலும் கொண்ட அந்த வீரனின் மனைவியாக நீ ஏன் விரும்பவில்லை?”',
        '0.11': '“பெருவலிமை மன்னன் ராவணன் தன் அன்புக்குரிய, மதிப்புமிக்க மனைவியை விட்டு, எல்லாரிலும் பெரும்பேறுடைய உன்னிடம் வருவான்.”',
        '0.12': '“ஆயிரம் பெண்களால் நிறைந்து, பலவகை ரத்தினங்களால் அழகுபெற்ற அந்த அந்தப்புரத்தை விட்டு ராவணன் உன்னிடம் வருவான்.”',
        '0.13': 'விகடை என்னும் மற்றோர் அரக்கி சொன்னாள்: “யாருடைய கொடிய வீரத்தால் நாகர், கந்தர்வர், தானவர் போரில் மீண்டும் மீண்டும் வெல்லப்பட்டனரோ அவனே உன் அருகில் வந்தான்.”',
        '0.14': '“இழிந்தவளே, எல்லாவற்றிலும் செழிப்புடைய மகாத்மாவான அரக்கர் வேந்தன் ராவணனின் மனைவியாக நீ ஏன் விரும்பவில்லை?”',
        '0.15': 'அப்போது துர்முகி என்னும் அரக்கி அவளிடம் சொன்னாள்: “நீண்ட கண்ணுடையவளே, யாருக்கு அஞ்சிக் கதிரவன் சுடுவதில்லையோ, காற்று வீசுவதில்லையோ, அவனுக்கு நீ ஏன் இணங்கவில்லை?”',
        '0.16': '“யாருக்கு அஞ்சி மரங்கள் மலர் மழை பொழிகின்றனவோ, அவன் விரும்பும்போது மலைகளும் மேகங்களும் நீரைப் பொழிகின்றனவோ —”',
        '0.17': '“அழகியே, மன்னர் மன்னனான அந்த அரக்கர் அரசன் ராவணனின் மனைவியாக நீ ஏன் மனம் வைக்கவில்லை?”',
        '0.18': '“தேவியே, அழகியே, நாங்கள் உனக்கு உண்மையாகவும் நன்மையாகவும் சொன்னோம்; புன்னகையாளே, எங்கள் சொல்லை ஏற்றுக்கொள், இல்லாவிட்டால் நீ உயிர் வாழமாட்டாய்.”',
        '0.19': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் இருபத்துமூன்றாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-24': {
      verses: {
        '0.0': 'அப்போது உருக்குலைந்த முகமுடைய அந்த அரக்கியர் அனைவரும் கடுமைக்குத் தகாத சீதையிடம் கடுமையான இனிமையற்ற சொற்களைச் சொன்னார்கள்.',
        '0.1': '“சீதையே, எல்லா உயிர்களுக்கும் இனிய, விலையுயர்ந்த படுக்கைகள் கொண்ட அந்தப்புரத்தில் வாழ நீ ஏன் ஒப்பவில்லை?”',
        '0.2': '“மானுடப் பெண்ணான நீ மனிதனின் மனைவியாக இருப்பதையே பெரிதாக மதிக்கிறாய். ராமனிடமிருந்து மனத்தைத் திருப்பு; அது ஒருபோதும் நடக்காது.”',
        '0.3': '“மூவுலகச் செல்வத்தையும் அனுபவிக்கும் அரக்கர் வேந்தன் ராவணனைக் கணவனாக அடைந்து இன்பமாக உலவு.”',
        '0.4': '“அழகியே, பழியற்றவளே, மானுடப் பெண்ணான நீ அரசிழந்த, நோக்கம் நிறைவேறாத, கலங்கிய அந்த மனிதன் ராமனையே விரும்புகிறாய்.”',
        '0.5': 'அரக்கியரின் சொற்களைக் கேட்டுத் தாமரைக் கண்ணாள் சீதை கண்ணீர் நிறைந்த கண்களுடன் இவ்வாறு சொன்னாள்:',
        '0.6': '“நீங்கள் அனைவரும் கூடிச் சொல்லும் உலகம் வெறுக்கும் இந்தப் பாவச் சொல் என் மனத்தில் நிலைக்காது.”',
        '0.7': '“மானுடப் பெண் அரக்கனின் மனைவியாக முடியாது. வேண்டுமானால் நீங்கள் அனைவரும் என்னைத் தின்னுங்கள்; உங்கள் சொல்படி நான் செய்யமாட்டேன்.”',
        '0.8': '“ஏழையோ அரசிழந்தவனோ, என் கணவனே எனக்குக் குரு. சுவர்ச்சலை கதிரவனிடம் போல நான் அவனிடம் எப்போதும் பற்றுடையவள்.”',
        '0.9': '“பெரும்பேறுடைய சசி இந்திரனையும், அருந்ததி வசிஷ்டரையும், ரோகிணி சந்திரனையும் பணிவது போல,”',
        '0.10': '“லோபாமுத்திரை அகஸ்தியரையும், சுகன்யை சியவனரையும், சாவித்திரி சத்தியவானையும், ஸ்ரீமதி கபிலரையும் பணிவது போல,”',
        '0.11': '“மதயந்தி சௌதாசனையும், கேசினி சகரனையும், கணவனைப் பின்பற்றும் பீமன் மகள் தமயந்தி நிஷத நாட்டு நளனையும் பணிவது போல —”',
        '0.12': '“அவ்வாறே நான் இக்ஷ்வாகு குலத்தில் சிறந்த என் கணவன் ராமனுக்கு உரியவள்.” சீதையின் சொற்களைக் கேட்டுச் சினத்தால் வெறிகொண்டு, ராவணனால் தூண்டப்பட்ட அரக்கியர் கடுஞ்சொற்களால் அவளை மிரட்டினர்.',
        '0.13': 'சிம்சுபா மரத்தில் மௌனமாக மறைந்திருந்த வானரன் ஹனுமான் சீதையை மிரட்டிய அந்த அரக்கியரின் சொற்களைக் கேட்டான்.',
        '0.14': 'நடுங்கிய அவளைச் சுற்றிலும் நெருங்கிய சினமுற்ற அரக்கியர் தங்கள் நீண்ட எரியும் உதடுகளை மீண்டும் மீண்டும் நக்கினர்.',
        '0.15': 'பெருஞ்சினத்துடன் விரைந்து கோடரிகளை ஏந்திச் சொன்னார்கள்: “அரக்கர் தலைவன் ராவணனைக் கணவனாகப் பெற இவள் தகுதியற்றவள்!”',
        '0.16': 'கொடிய அரக்கியரால் மிரட்டப்பட்ட அந்த அழகி கண்ணீரைத் துடைத்தபடி அந்தச் சிம்சுபா மரத்தருகே சென்றாள்.',
        '0.17': 'அப்போது அரக்கியரால் சூழப்பட்ட பெருங்கண்ணாள் சீதை அந்தச் சிம்சுபா மரத்தை அடைந்து துயரில் மூழ்கி நின்றாள்.',
        '0.18': 'மெலிந்து, வாடிய முகத்துடன், அழுக்கு ஆடை உடுத்திய அவளைச் சுற்றியிருந்த கொடிய அரக்கியர் மிரட்டத் தொடங்கினர்.',
        '0.19': 'அப்போது வினதை என்னும் கொடிய தோற்றமும், சினமுற்ற முகமும், கோரமும், உள்வாங்கிய வயிறும் கொண்ட அரக்கி சொன்னாள்:',
        '0.20': '“சீதையே, கணவன் மீதான அன்பைப் போதுமான அளவு காட்டிவிட்டாய். நல்லவளே, எதிலும் அளவுமீறல் கேட்டுக்கே வழிவகுக்கும்.”',
        '0.21': '“உன்னிடம் மகிழ்ந்தேன், உனக்கு நலம் உண்டாகட்டும்; மனிதருக்குரிய முறையை நீ கடைப்பிடித்தாய். ஆனால் மைதிலியே, நன்மை சொல்லும் என் சொல்லையும் கேள்.”',
        '0.22': '“எல்லா அரக்கர்களின் தலைவனும், தேவர் தலைவன் இந்திரன் போல வீரமும் பாய்ச்சலும் கொண்டவனுமான ராவணனைக் கணவனாக ஏற்றுக்கொள்.”',
        '0.23': '“பரிதாபமான மனிதன் ராமனை விட்டு, தாராள மனமும் கொடைத்தன்மையும் கொண்டு எல்லோரிடமும் இனிமையாகப் பேசும் ராவணனைச் சரணடை.”',
        '0.24': '“வைதேகியே, தெய்வீகப் பூச்சுகளும் தெய்வீக அணிகலன்களும் பூண்டு இன்று முதல் எல்லா உலகங்களுக்கும் அரசியாகு,”',
        '0.25': '“அழகியே, அக்னிக்கு ஸ்வாஹா தேவி போலவும் இந்திரனுக்குச் சசி போலவும். வைதேகியே, பரிதாபமானவனும் ஆயுள் முடிந்தவனுமான ராமனால் உனக்கு என்ன?”',
        '0.26': '“நான் சொன்ன இந்தச் சொல்படி நீ செய்யாவிட்டால் இதே கணத்தில் நாங்கள் அனைவரும் உன்னைத் தின்றுவிடுவோம்.”',
        '0.27': 'தொங்கும் மார்பகங்களுடைய விகடை என்னும் மற்றொருத்தி சினத்துடன் முஷ்டியை உயர்த்திச் சீதையை மிரட்டியபடி சொன்னாள்:',
        '0.28': '“கெட்ட புத்தியுடைய மைதிலியே, இரக்கத்தாலும் மென்மையாலும் உன் பல தகாத சொற்களை நாங்கள் பொறுத்துக்கொண்டோம்.”',
        '0.29': '“ஆயினும் எங்கள் காலத்துக்கேற்ற நல்லுரையை நீ ஏற்கவில்லை. பிறரால் அணுக முடியாத கடலின் அக்கரைக்கு நீ கொண்டுவரப்பட்டிருக்கிறாய்.”',
        '0.30': '“மைதிலியே, ராவணனின் கொடிய அந்தப்புரத்தில் நீ நுழைந்துவிட்டாய்; ராவணன் வீட்டில் அடைக்கப்பட்டு எங்களால் காக்கப்படுகிறாய்.”',
        '0.31': '“நேரடிப் புரந்தரனாலும் (இந்திரனாலும்) உன்னைக் காப்பாற்ற இயலாது. மைதிலியே, நன்மை சொல்லும் என் சொல்படி செய்.”',
        '0.32': '“கண்ணீர் சிந்தியது போதும்; பயனற்ற துயரத்தை விடு. எப்போதும் உள்ள துயர நிலையைக் கைவிட்டு அன்பையும் மகிழ்ச்சியையும் ஏற்றுக்கொள்.”',
        '0.33': '“சீதையே, அரக்கர் அரசனுடன் இன்பமாக விளையாடு. அஞ்சுபவளே, பெண்களின் இளமை எவ்வளவு நிலையற்றது என்பது எங்களுக்குத் தெரியும்.”',
        '0.34': '“அது கடந்துபோகும் முன் இன்பத்தை அனுபவி; அழகிய உத்யானங்களிலும் மலைச் சோலைகளிலும் —”',
        '0.35': '“மயக்கும் கண்ணாளே, அரக்கர் அரசனுடன் உலவு. அழகிய தேவியே, ஆயிரக்கணக்கான பெண்கள் உன் ஆணைக்குக் கட்டுப்படுவார்கள்.”',
        '0.36': '“எல்லா அரக்கர்களின் தலைவனான ராவணனைக் கணவனாக ஏற்றுக்கொள்; இல்லாவிட்டால் மைதிலியே, உன் இதயத்தைப் பிடுங்கித் தின்பேன்,”',
        '0.37': '“நான் சொன்னபடியே நீ செய்யாவிட்டால்.” அப்போது கொடிய தோற்றமுடைய சண்டோதரி என்னும் அரக்கி,',
        '0.38': 'பெரிய சூலத்தைச் சுழற்றியபடி சொன்னாள்: “மான்குட்டிக் கண்ணுடைய, அச்சத்தால் நடுங்கும் மார்புடைய இவளை —”',
        '0.39': '“ராவணன் கவர்ந்து வந்ததைக் கண்டது முதல் எனக்கு இந்தப் பெரும் ஆசை எழுந்துள்ளது: இவளுடைய கல்லீரல், மண்ணீரல், அகன்ற மார்பு, நரம்புகளுடன் இதயம்,”',
        '0.40': '“அங்கங்களையும் தலையையும் — இவற்றைத் தின்னவேண்டும் என்பது என் எண்ணம்.” அப்போது பிரகசை என்னும் அரக்கி சொன்னாள்:',
        '0.41': '“இந்தக் கொடியவளின் கழுத்தை நெரிப்போம்; ஏன் சும்மா இருக்கிறோம்? பின்னர் அந்த மானுடப் பெண் இறந்துவிட்டாள் என்று அரசனுக்குத் தெரிவிப்போம்.”',
        '0.42': '“இதில் ஐயமே இல்லை; அவன் ‘தின்னுங்கள்’ என்பான்.” அப்போது அஜாமுகி என்னும் அரக்கி சொன்னாள்:',
        '0.43': '“இவளை வெட்டி எல்லோருக்கும் சமமான பங்குகளாக்குங்கள்; பின்னர் நாம் அனைவரும் பகிர்ந்துகொள்வோம். எனக்குச் சண்டை பிடிக்காது.”',
        '0.44': '“விரைவில் பானத்தையும் பலவகை மாலைகள் பலவற்றையும் கொண்டு வாருங்கள்.” அப்போது சூர்ப்பணகை என்னும் அரக்கி சொன்னாள்:',
        '0.45': '“அஜாமுகி சொன்னதே எனக்கும் பிடித்திருக்கிறது. எல்லாத் துயரங்களையும் போக்கும் கள்ளை விரைவில் கொண்டு வாருங்கள்.”',
        '0.46': '“மனித இறைச்சியைச் சுவைத்துப் பின்னர் நிகும்பிலையின் முன் ஆடுவோம்.” விகார உருவுடைய அரக்கியர் இவ்வாறு மிரட்ட, தேவமகள் போன்ற சீதை துணிவிழந்து அழுதாள்.',
        '0.47': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் இருபத்துநான்காம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-25': {
      verses: {
        '0.0': 'அந்தக் கொடிய அரக்கியர் பல கடுமையான பயங்கரச் சொற்களைச் சொல்லிக்கொண்டிருக்க, ஜனகன் மகள் அழுதாள்.',
        '0.1': 'அரக்கியர் இவ்வாறு சொல்ல, மனவுறுதியுடைய வைதேகி மிகவும் அஞ்சிக் கண்ணீரால் தழுதழுத்த குரலில் சொன்னாள்:',
        '0.2': '“மானுடப் பெண் அரக்கனின் மனைவியாக முடியாது. வேண்டுமானால் நீங்கள் அனைவரும் என்னைத் தின்னுங்கள்; உங்கள் சொல்படி நான் செய்யமாட்டேன்.”',
        '0.3': 'அரக்கியரிடையே இருந்த தேவமகள் போன்ற சீதை, ராவணன் மிரட்டியபோது போலவே துயரில் வாடி அமைதி காணவில்லை.',
        '0.4': 'காட்டில் மந்தையைப் பிரிந்து ஓநாய்களால் துரத்தப்பட்ட பெண்மான் போல, சீதை தன் உடலுக்குள்ளேயே ஒடுங்குவது போல மேலும் நடுங்கினாள்.',
        '0.5': 'அசோகத்தின் பூத்த பெரிய கிளையைப் பற்றிக்கொண்டு, துயரால் மனமுடைந்த அவள் தன் கணவனை நினைத்தாள்.',
        '0.6': 'கண்ணீர்த் தாரைகளால் தன் மார்பகங்களை நனைத்தபடி சிந்தனையில் ஆழ்ந்த அவள் அப்போது துயரத்துக்கு முடிவு காணவில்லை.',
        '0.7': 'புயலில் வாழைமரம் போல நடுங்கி அவள் விழுந்தாள்; அரக்கியர் மீதான அச்சத்தால் அவள் முகம் வெளிறியது.',
        '0.8': 'அவள் நடுங்கும்போது அசைந்த அவளுடைய நீண்ட அடர்ந்த சடை ஊர்ந்து செல்லும் பாம்பு போலத் தோன்றியது.',
        '0.9': 'பெருமூச்செறிந்து, துயரால் வாடி, மனம் கலங்கிய மைதிலி வேதனையுடன் கண்ணீர் சொரிந்து புலம்பினாள்,',
        '0.10': 'துயரத்துடன் “ஹா ராமா!”, மீண்டும் “ஹா லக்ஷ்மணா!”, “ஹா என் மாமியார் கௌசல்யையே! ஹா சுமித்திரையே!” என்று அந்த அழகி கதறினாள்.',
        '0.11': '“அறிஞர்கள் எடுத்துரைக்கும் இந்த உலக வழக்கு உண்மையே: பெண்ணுக்கோ ஆணுக்கோ காலம் வருமுன் மரணம் கிடைப்பது அரிது.”',
        '0.12': '“ஏனெனில் இந்தக் கொடிய அரக்கியரால் இங்கே துன்புறுத்தப்பட்டு, ராமனைப் பிரிந்து, துயருற்றும் நான் கணநேரமாவது உயிர் வாழ்கிறேன்.”',
        '0.13': '“சிறு புண்ணியமுடைய பரிதாபமான நான், கடலின் நடுவே காற்றின் வேகத்தால் தாக்கப்பட்ட சுமை நிறைந்த கப்பல் போல, ஆதரவற்றவளாக அழிவேன்.”',
        '0.14': '“கணவனைக் காணாமல் அரக்கியர் பிடியில் சிக்கிய நான், நீரால் அரிக்கப்படும் கரை போலத் துயரால் சரிந்துகொண்டிருக்கிறேன்.”',
        '0.15': '“தாமரை இதழ்க் கண்களும் சிங்க நடையும் கொண்ட, நன்றியுடைய, இனிமையாகப் பேசும் என் நாதனைக் காண்பவர்கள் பாக்கியசாலிகள்.”',
        '0.16': '“தன்னை அறிந்தவனான ராமனை முற்றிலும் பிரிந்த எனக்கு, கொடிய நஞ்சை உண்டது போல உயிர் வாழ்வது அரிதாகிவிட்டது.”',
        '0.17': '“முற்பிறவியில் நான் எத்தகைய பெரும் பாவம் செய்தேனோ, அதனால்தான் இந்தக் கொடிய மிகக் கடுமையான பெருந்துயரை அடைகிறேன்.”',
        '0.18': '“பெருந்துயரால் சூழப்பட்ட நான் உயிர் துறக்க விரும்புகிறேன்; அரக்கியரின் காவலில் இருக்கும் என்னால் ராமனை அடைய இயலவில்லை.”',
        '0.19': '“மனிதப் பிறவிக்கு ஐயோ! பிறர் வசப்பட்டிருப்பதற்கு ஐயோ! தன் விருப்பப்படி உயிரைக் கூட விட இயலவில்லையே!”',
        '0.20': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் இருபத்தைந்தாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
    'sundarakanda-26': {
      verses: {
        '0.0': 'இவ்வாறு சொல்லியபடி, கண்ணீர் வழியும் முகத்துடன் ஜனகன் மகளான அந்த இளம்பெண் தலைகுனிந்து புலம்பத் தொடங்கினாள்.',
        '0.1': 'பித்துப் பிடித்தவள் போலவும், தன்னிலை மறந்தவள் போலவும், மனம் குழம்பியவள் போலவும் புலம்பியபடி, இளம் பெண்குதிரை போலத் தரையில் புரண்டாள்.',
        '0.2': '“ராகவன் கவனமின்றி இருந்தபோது விரும்பிய உருவெடுக்கும் அரக்கன் ராவணன் நான் கதறியும் என்னை வலிந்து பிடித்துக் கொண்டுவந்தான்.”',
        '0.3': '“அரக்கியர் பிடியில் சிக்கி, கொடூரமாக மிரட்டப்பட்டு, பெருந்துயரில் சிந்திக்கும் எனக்கு உயிர் வாழும் ஊக்கம் இல்லை.”',
        '0.4': '“மாவீரனான ராமன் இல்லாமல் அரக்கியரிடையே வாழும் எனக்கு உயிராலோ செல்வத்தாலோ அணிகலன்களாலோ எந்தப் பயனும் இல்லை.”',
        '0.5': '“என் இந்த இதயம் நிச்சயமாக இரும்பால் ஆனது, அல்லது மூப்பும் சாவும் இல்லாதது; ஏனெனில் இந்தத் துயரத்தால் அது உடையவில்லை.”',
        '0.6': '“அவனைப் பிரிந்தும் கணநேரமாவது உயிர் வாழும் இழிந்தவளும் கற்பற்றவளுமான எனக்கு ஐயோ; இந்த வாழ்வு பாவ வாழ்வு.”',
        '0.7': '“அந்த இரவில் திரிபவன் ராவணனை என் இடக்காலால் கூடத் தொடமாட்டேன்; அப்படியிருக்க அந்த இழிந்தவனை எப்படி விரும்புவேன்?”',
        '0.8': '“தன் கொடிய இயல்பால் என்னை நாடும் அவனுக்கு மறுப்பும் புரியவில்லை, தன்னையும் தன் குலத்தையும் அறியவில்லை.”',
        '0.9': '“வெட்டப்பட்டாலும், பிளக்கப்பட்டாலும், சிதைக்கப்பட்டாலும், எரியும் தீயில் எரிக்கப்பட்டாலும் நான் ராவணனுக்கு இணங்கமாட்டேன். நீங்கள் நெடுநேரம் பிதற்றுவதால் என்ன?”',
        '0.10': '“ராகவன் அறிவாளியும் நன்றியுடையவனும் இரக்கமுடையவனும் எனப் புகழ்பெற்றவன்; ஆனால் என் பாக்கியம் தேய்ந்ததால் அந்த நல்லொழுக்கமுடையவன் இரக்கமற்றவனாகிவிட்டானோ என்று ஐயுறுகிறேன்.”',
        '0.11': '“ஜனஸ்தானத்தில் பதினான்காயிரம் அரக்கர்களைத் தனியொருவனாக அழித்தவன் ஏன் என்னிடம் வரவில்லை?”',
        '0.12': '“சிறிய ஆற்றலுடைய அரக்கன் ராவணனால் நான் சிறைப்பட்டுள்ளேன்; என் கணவன் போரில் ராவணனைக் கொல்ல நிச்சயம் வல்லவன்.”',
        '0.13': '“தண்டகாரண்யத்தில் அரக்கருள் சிறந்த விராதனைப் போரில் கொன்ற ராமன் ஏன் என்னிடம் வரவில்லை?”',
        '0.14': '“கடல் நடுவே உள்ள இந்த இலங்கை வெல்லக் கடினமானதாக இருக்கலாம்; ஆனால் ராகவனின் அம்புகளின் போக்கை எதுவும் தடுக்காது.”',
        '0.15': '“உறுதியான வீரமுடைய ராமன், அரக்கனால் கவரப்பட்ட தன் அன்பு மனைவிக்காக வராததற்குக் காரணம் என்னவாக இருக்கும்?”',
        '0.16': '“லக்ஷ்மணனின் அண்ணனுக்கு நான் இங்கே இருப்பது தெரியாது என்று ஐயுறுகிறேன்; தெரிந்திருந்தால் அந்த ஒளியுடையவன் இந்த அவமானத்தைப் பொறுப்பானா?”',
        '0.17': '“நான் கவரப்பட்டதை அறிந்து ராகவனிடம் சொல்லக்கூடியவனான கழுகரசனும் போரில் ராவணனால் வீழ்த்தப்பட்டான்.”',
        '0.18': '“எனக்கு உதவ வந்து ராவணனைக் கொல்ல எதிர்த்து நின்ற முதிய ஜடாயு பெருஞ்செயலையே செய்தான்.”',
        '0.19': '“நான் இங்கே உயிரோடிருப்பது ராகவனுக்குத் தெரிந்தால் இன்றே சினந்து அம்புகளால் உலகை அரக்கரற்றதாக்குவான்,”',
        '0.20': '“இலங்கை நகரை எரிப்பான், பெருங்கடலையும் வற்றச் செய்வான், இழிந்த ராவணனின் புகழையும் பெயரையும் அழிப்பான்.”',
        '0.21': '“அப்போது கணவர்களை இழந்த அரக்கியர் வீடுதோறும் நான் இப்போது அழுவது போலவே அழுவார்கள், ஐயமில்லை.”',
        '0.22': '“இலங்கையின் அரக்கர்களைத் தேடி ராமன் லக்ஷ்மணனுடன் இவ்வாறு செய்வான்; அவ்விருவர் கண்ணில் பட்ட பகைவன் கணநேரமும் உயிர் வாழ்வதில்லை.”',
        '0.23': '“விரைவிலேயே சிதைப் புகையால் நிறைந்த தெருக்களுடனும் கழுகுக் கூட்டங்கள் சூழவும் இலங்கை சுடுகாடு போலாகும்.”',
        '0.24': '“விரைவில் என் இந்த விருப்பம் நிறைவேறும். உங்களின் இந்தத் தீய நடத்தை உங்கள் அனைவரின் அழிவையே குறிக்கிறது.”',
        '0.25': '“இலங்கையில் இப்போது காணப்படும் தீய சகுனங்களைக் கொண்டு பார்த்தால் விரைவில் அது ஒளியிழக்கும்.”',
        '0.26': '“பாவியான அரக்கர் தலைவன் ராவணன் கொல்லப்பட்டதும், வெல்லற்கரிய இலங்கை விதவைப் பெண் போல வாடிப்போவது உறுதி.”',
        '0.27': '“புனிதத் திருவிழாக்களால் செழித்த இலங்கை நகர் அரக்கர்களுடன் தலைவனை இழந்து, கணவனை இழந்த பெண் போலாகும்.”',
        '0.28': '“விரைவிலேயே இங்கே வீடுதோறும் துயரால் அழும் அரக்கக் கன்னியரின் ஓலத்தை நான் நிச்சயம் கேட்பேன்.”',
        '0.29': '“ராமனின் அம்புகளால் எரிக்கப்பட்ட இலங்கை நகர் இருளில் மூழ்கி, ஒளி அணைந்து, அரக்கர் தலைவர்கள் கொல்லப்பட்டதாகும்.”',
        '0.30': '“செவ்வோரக் கண்களுடைய அந்த வீரன் ராமனுக்கு நான் அரக்கனின் வீட்டில் உயிரோடிருப்பது தெரிந்தால் போதுமே!”',
        '0.31': '“ஆனால் இந்தக் கொடிய இழிந்த ராவணன் எனக்கு விதித்த கெடுவின் காலம் இப்போது வந்துவிட்டது.”',
        '0.32': '“அந்தத் தீயவன் எனக்கு விதித்த மரணம் இப்போது நெருங்கிவிட்டது; பாவம் புரியும் இந்த அரக்கர்களுக்குச் செய்யத் தகாதது எது என்று தெரியாது.”',
        '0.33': '“இந்த அதர்மத்தால் இப்போது பெரும் கேடு நிகழும்; இறைச்சி உண்ணும் இந்த அரக்கர்களுக்கு அறம் தெரியாது.”',
        '0.34': '“அந்த அரக்கன் நிச்சயமாக என்னைக் காலை உணவாக்கிக்கொள்வான்; அழகிய என் கணவன் இல்லாமல் நான் என்ன செய்வேன்?”',
        '0.35': '“செவ்வோரக் கண்ணுடைய ராமனைக் காணாமல் மிகவும் துயருற்ற நான் கணவன் இன்றியே விரைவில் வைவஸ்வத (யம) தேவனைக் காண்பேன்.”',
        '0.36': '“நான் உயிரோடிருப்பது பரதனின் அண்ணன் ராமனுக்குத் தெரியாது; தெரிந்திருந்தால் அவ்விருவரும் பூமி முழுவதும் தேடாமல் இருக்கமாட்டார்கள்.”',
        '0.37': '“லக்ஷ்மணனின் அண்ணனான அந்த வீரன் என் துயரத்தாலேயே பூமியில் உடலை விட்டு இங்கிருந்து தேவலோகம் சென்றிருப்பான்.”',
        '0.38': '“என் வீரனான தாமரைக் கண்ணன் ராமனைக் காணும் தேவர்களும் கந்தர்வர்களும் சித்தர்களும் மாமுனிவர்களும் பாக்கியசாலிகள்.”',
        '0.39': '“அல்லது அறத்தையே நாடும் அறிவுடைய ராஜரிஷியான மகாத்மா ராமனுக்கு மனைவியான என்னால் எந்தப் பயனும் இல்லையோ.”',
        '0.40': '“கண்முன் இருக்கும்போதுதான் அன்பு உண்டு, கண்ணுக்கு மறைந்தவரிடம் பாசம் இல்லை. ஆனால் நன்றி கெட்டவர்களே அன்பை அழிப்பர்; ராமன் அழிக்கமாட்டான்.”',
        '0.41': '“அல்லது என்னிடம் ஏதேனும் குறைகள் உள்ளனவோ, அல்லது என் பாக்கியம் தீர்ந்துவிட்டதோ — சிறந்ததற்கே தகுந்த ராமனை அழகி சீதையான நான் பிரிந்துள்ளேனே.”',
        '0.42': '“களங்கமற்ற ஒழுக்கமுடைய, வீரனும் பகைவரை அழிப்பவனுமான மகாத்மா ராமனைப் பிரிந்த எனக்கு உயிர் வாழ்வதை விட இறப்பதே நன்று.”',
        '0.43': '“அல்லது மனிதருள் சிறந்த அந்த இரு சகோதரர்களும் ஆயுதங்களைக் கீழே வைத்துக் கிழங்கும் கனியும் உண்டு காட்டுவாசிகளாக வனத்தில் திரிந்துகொண்டிருக்கலாம்.”',
        '0.44': '“அல்லது வீரச் சகோதரர்களான ராம லக்ஷ்மணரைத் தீய மனமுடைய அரக்கர் வேந்தன் ராவணன் சூழ்ச்சியால் கொல்லச் செய்திருக்கலாம்.”',
        '0.45': '“ஆகவே இத்தகைய நேரத்தில் நான் எல்லா வகையிலும் இறக்க விரும்புகிறேன்; ஆயினும் இந்தப் பெருந்துயரில் எனக்கு மரணம் விதிக்கப்படவில்லை.”',
        '0.46': '“உண்மையால் மதிக்கப்படுபவர்களும், புலன்களை வென்றவர்களும், பெரும்பேறுடையவர்களும், விருப்பு வெறுப்பு இல்லாதவர்களுமான மகாத்மா முனிவர்கள் உண்மையில் பாக்கியசாலிகள்.”',
        '0.47': '“விருப்பமானதால் துயர் பிறக்கிறது, விருப்பமற்றதால் அதைவிட அதிகம்; அவர்கள் இவ்விரண்டிலிருந்தும் விடுபட்டவர்கள் — அந்த மகாத்மாக்களுக்கு வணக்கம்.”',
        '0.48': '“தன்னை அறிந்தவனான என் அன்புக்குரிய ராமனால் கைவிடப்பட்டு, பாவி ராவணனின் பிடியில் சிக்கிய நான் உயிர் துறப்பேன்.”',
        '0.49': 'இவ்வாறு வால்மீகி முனிவர் அருளிய ஆதிகாவியமான ஸ்ரீமத் ராமாயணத்தின் சுந்தர காண்டத்தில் இருபத்தாறாம் ஸர்க்கம் நிறைவுறுகிறது.',
      },
    },
  },
};
